function normalizeVaccineSpecies(
  value
) {
  const raw =
    String(value || "")
      .trim()
      .toLowerCase();

  if (
    [
      "dog",
      "СЃРѕР±Р°РєР°",
      "РїРµСЃ",
    ].includes(raw)
  ) {
    return "dog";
  }

  if (
    [
      "cat",
      "РєС–С‚",
      "РєС–С€РєР°",
      "РєРѕС‚",
      "РєРѕС€РєР°",
    ].includes(raw)
  ) {
    return "cat";
  }

  return "other";
}


