function getVaccineBrandsForPatient(
  pet
) {
  const species =
    normalizeVaccineSpecies(
      pet?.species
    );

  return VACCINE_CATALOG.filter(
    (brand) =>
      brand.species.includes(
        species
      )
  );
}
