function getUaPhoneDigits(
  value
) {
  let digits =
    String(value || "")
      .replace(/\D/g, "");

  if (
    digits.startsWith("380")
  ) {
    return digits.slice(
      0,
      12
    );
  }

  if (
    digits.startsWith("0")
  ) {
    digits =
      `38${digits}`;
  } else if (
    digits.length <= 9
  ) {
    digits =
      `380${digits}`;
  }

  return digits.slice(
    0,
    12
  );
}


function formatUaPhone(
  value
) {
  const digits =
    getUaPhoneDigits(
      value
    );

  if (!digits) {
    return "";
  }

  let result = "+";

  result +=
    digits.slice(0, 3);

  if (digits.length > 3) {
    result +=
      ` ${digits.slice(3, 5)}`;
  }

  if (digits.length > 5) {
    result +=
      ` ${digits.slice(5, 8)}`;
  }

  if (digits.length > 8) {
    result +=
      ` ${digits.slice(8, 10)}`;
  }

  if (digits.length > 10) {
    result +=
      ` ${digits.slice(10, 12)}`;
  }

  return result;
}


function isValidUaPhone(
  value
) {
  const digits =
    String(value || "")
      .replace(/\D/g, "");

  return (
    digits.length === 12 &&
    digits.startsWith("380")
  );
}


function bindUaPhoneInput(
  input
) {
  if (
    !input ||
    input.dataset
      .phoneMaskBound === "1"
  ) {
    return;
  }

  input.dataset.phoneMaskBound =
    "1";

  input.setAttribute(
    "maxlength",
    "17"
  );

  input.setAttribute(
    "inputmode",
    "numeric"
  );

  input.addEventListener(
    "keydown",
    (event) => {
      const allowedKeys = [
        "Backspace",
        "Delete",
        "ArrowLeft",
        "ArrowRight",
        "Tab",
        "Home",
        "End",
      ];

      if (
        allowedKeys.includes(
          event.key
        )
      ) {
        return;
      }

      if (
        event.ctrlKey ||
        event.metaKey
      ) {
        return;
      }

      if (
        !/^\d$/.test(
          event.key
        )
      ) {
        event.preventDefault();
      }
    }
  );

  input.addEventListener(
    "paste",
    (event) => {
      event.preventDefault();

      const pasted =
        event.clipboardData
          ?.getData("text") ||
        "";

      input.value =
        formatUaPhone(
          pasted
        );

      input.dispatchEvent(
        new Event(
          "input",
          {
            bubbles: true,
          }
        )
      );
    }
  );

  input.addEventListener(
    "input",
    () => {
      input.value =
        formatUaPhone(
          input.value
        );

      input.setCustomValidity(
        ""
      );
    }
  );

  input.addEventListener(
    "blur",
    () => {
      if (
        input.value &&
        !isValidUaPhone(
          input.value
        )
      ) {
        input.setCustomValidity(
          "РўРµР»РµС„РѕРЅ РїРѕРІРёРЅРµРЅ РјС–СЃС‚РёС‚Рё СЂС–РІРЅРѕ 12 С†РёС„СЂ Сѓ С„РѕСЂРјР°С‚С– +380 XX XXX XX XX"
        );
      } else {
        input.setCustomValidity(
          ""
        );
      }
    }
  );
}


