function closeDeleteModal() {
  const modal =
    $("#deleteModal");

  const cancelBtn =
    $("#deleteCancel");

  if (modal) {
    modal.style.display =
      "none";

    modal.classList.remove(
      "is-success",
      "is-payment-cancel"
    );
  }

  if (cancelBtn) {
    cancelBtn.style.display =
      "";

    cancelBtn.textContent =
      "РЎРєР°СЃСѓРІР°С‚Рё";
  }

  deleteCallback =
    null;
}

