function getCurrentCrmRole() {
  const role =
    String(
      state.me?.role || "vet"
    )
      .trim()
      .toLowerCase();

  return CRM_ROLE_ACCESS[role]
    ? role
    : "vet";
}


function getCurrentStaffId() {
  return String(
    state.me?.staff_id || ""
  ).trim();
}
function getCurrentVetWaitingEvents(
  events = []
) {
  const currentStaffId =
    getCurrentStaffId();

  if (!currentStaffId) {
    return [];
  }

  return (
    Array.isArray(events)
      ? events
      : []
  ).filter(
    (event) => {
      const eventStaffId =
        String(
          event?.staff_id || ""
        ).trim();

      const eventStatus =
        String(
          event?.status || ""
        )
          .trim()
          .toLowerCase();

      return (
        eventStaffId ===
          currentStaffId &&
        eventStatus ===
          "waiting"
      );
    }
  );
}

async function checkCurrentVetWaitingPatients() {
  try {
    const events =
      await loadCalendarApi();

    const waitingEvents =
      getCurrentVetWaitingEvents(
        events
      );
      renderWaitingPatientAlert(
  waitingEvents
);


    events.forEach(
      (event) => {
        const eventId =
          String(
            event?.id || ""
          ).trim();

        if (!eventId) {
          return;
        }

        const eventStatus =
          String(
            event?.status || ""
          )
            .trim()
            .toLowerCase();

        if (
          eventStatus !==
          "waiting"
        ) {
          sessionStorage.removeItem(
            `waiting_notice_${eventId}`
          );
        }
      }
    );
if (
  state.route ===
  "calendar"
) {
  await renderCalendarTab();
}
  } catch (error) {
    console.warn(
      "checkCurrentVetWaitingPatients failed:",
      error
    );
  }
}
