// ===== API: Owners =====
// ===== API: Owners =====
let ownersApiInFlight =
  null;


async function loadOwners(
  force = false
) {
  if (
    ownersApiInFlight &&
    !force
  ) {
    return ownersApiInFlight;
  }


  const cachedOwners =
    Array.isArray(
      state.owners
    ) &&
    state.owners.length
      ? state.owners
      : (
          Array.isArray(
            LS.get(
              OWNERS_KEY,
              []
            )
          )
            ? LS.get(
                OWNERS_KEY,
                []
              )
            : []
        );


  ownersApiInFlight =
    (async () => {
      const attempts = 3;

      const delays = [
        0,
        350,
        900,
      ];


      for (
        let attempt = 0;
        attempt < attempts;
        attempt++
      ) {
        if (
          delays[attempt]
        ) {
          await new Promise(
            (resolve) =>
              setTimeout(
                resolve,
                delays[attempt]
              )
          );
        }


        try {
          const response =
            await fetch(
              "/api/owners",
              {
                method:
                  "GET",

                credentials:
                  "include",

                cache:
                  "no-store",

                headers: {
                  Accept:
                    "application/json",

                  ...getOrgHeaders(),
                },
              }
            );


          const text =
            await response.text();


          let json = null;

          try {
            json =
              text
                ? JSON.parse(
                    text
                  )
                : null;

          } catch (
            parseError
          ) {
            throw new Error(
              "РЎРµСЂРІРµСЂ РїРѕРІРµСЂРЅСѓРІ РЅРµРєРѕСЂРµРєС‚РЅСѓ РІС–РґРїРѕРІС–РґСЊ."
            );
          }


          if (
            !response.ok ||
            !json ||
            json.ok !== true
          ) {
            throw new Error(
              json?.error ||
              `HTTP ${response.status}`
            );
          }


          const owners =
            Array.isArray(
              json.data
            )
              ? json.data
              : json.data
                ? [
                    json.data
                  ]
                : [];


          state.owners =
            owners;


          LS.set(
            OWNERS_KEY,
            owners
          );


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          if (
            state.route ===
              "owner" &&
            state.selectedOwnerId
          ) {
            await renderOwnerPage(
              state.selectedOwnerId
            );
          }


          return owners;

        } catch (error) {
          console.warn(
            `loadOwners attempt ${
              attempt + 1
            }/${attempts} failed:`,
            error
          );


          if (
            attempt <
            attempts - 1
          ) {
            continue;
          }


          console.error(
            "loadOwners failed after retries:",
            error
          );


          /*
           * Р’РђР–РќРћ:
           * РїСЂРё РІСЂРµРјРµРЅРЅРѕР№ РѕС€РёР±РєРµ
           * РќР• РѕС‡РёС‰Р°РµРј РІР»Р°РґРµР»СЊС†РµРІ.
           */

          state.owners =
            cachedOwners;


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          return cachedOwners;
        }
      }


      return cachedOwners;
    })();


  try {
    return await ownersApiInFlight;

  } finally {
    ownersApiInFlight =
      null;
  }
}
// ===== API: Patients =====
let patientsApiInFlight = null;
let patientsApiLoading = false;
let patientsApiLoaded = false;

async function loadPatientsApi() {
  if (patientsApiInFlight) {
    return patientsApiInFlight;
  }

  patientsApiLoading = true;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  patientsApiInFlight =
    loadPatientsApiRequest();

  try {
    return await patientsApiInFlight;
  } finally {
  patientsApiLoaded = true;
  patientsApiLoading = false;
  patientsApiInFlight = null;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  if (state.route === "owners") {
    renderOwners();
  }

  if (
    state.route === "owner" &&
    state.selectedOwnerId
  ) {
    await renderOwnerPage(
      state.selectedOwnerId
    );
  }
}
}

async function loadPatientsApiRequest() {
  const cachedPatients =
    Array.isArray(state.patients)
      ? state.patients
      : [];

  try {
    const res = await fetch("/api/patients", {
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    });

    const text = await res.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (!res.ok) {
      console.error(
        "API /patients HTTP",
        res.status,
        text
      );

      alert(
        `РџРѕРјРёР»РєР° Р·Р°РІР°РЅС‚Р°Р¶РµРЅРЅСЏ РїР°С†С–С”РЅС‚С–РІ (HTTP ${res.status})`
      );

      state.patients =
        cachedPatients;

      if (state.route === "patients") {
        renderPatientsTab();
      }

      if (
        state.route === "owner" &&
        state.selectedOwnerId
      ) {
        await renderOwnerPage(
          state.selectedOwnerId
        );
      }

      return cachedPatients;
    }

    if (!json || !json.ok) {
      console.error(
        "API /patients bad json",
        json,
        text
      );

      alert(
        json?.error ||
        "РџРѕРјРёР»РєР° Р·Р°РІР°РЅС‚Р°Р¶РµРЅРЅСЏ РїР°С†С–С”РЅС‚С–РІ"
      );

      state.patients =
        cachedPatients;

      if (state.route === "patients") {
        renderPatientsTab();
      }

      if (
        state.route === "owner" &&
        state.selectedOwnerId
      ) {
        await renderOwnerPage(
          state.selectedOwnerId
        );
      }

      return cachedPatients;
    }

    const arr = Array.isArray(json.data)
      ? json.data
      : json.data
        ? [json.data]
        : [];

    state.patients = arr;

    savePatients(arr);

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(
        state.selectedOwnerId
      );
    }

    return arr;
  } catch (e) {
    console.error(
      "loadPatientsApi failed:",
      e
    );

    alert(
      "РџРѕРјРёР»РєР° Р·Р°РІР°РЅС‚Р°Р¶РµРЅРЅСЏ РїР°С†С–С”РЅС‚С–РІ (network)"
    );

    state.patients =
      cachedPatients;

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(
        state.selectedOwnerId
      );
    }

    return cachedPatients;
  }
}

