async function loadServicesApi() {
  try {
    const res = await fetch("/api/services", {
      credentials: "include",
      headers: { Accept: "application/json", ...getOrgHeaders() },
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (
  !res.ok ||
  !json ||
  !json.ok
) {
  console.warn(
    "loadServicesApi failed:",
    res.status,
    text
  );

  state.services = [];

  return [];
}

    const arr = Array.isArray(json.data) ? json.data : (json.data ? [json.data] : []);
    const catMap = loadServicesCatMap();

    const merged = (Array.isArray(arr) ? arr : []).map((s) => {
      const id = String(s?.id || "");
      const savedCat = catMap[id];
      const rawCat = (s?.cat ?? s?.category ?? s?.section ?? s?.group ?? s?.type ?? savedCat ?? "");
      const cat = String(rawCat || "").trim() || "Р†РЅС€Рµ";
      return { ...s, cat };
    });

    state.services = merged;
    LS.set(SERVICES_KEY, merged);
    return merged;
  } catch (e) {
  console.warn(
    "loadServicesApi network fail:",
    e
  );

  state.services = [];

  return [];
}
}
async function loadAppointmentTemplatesApi(
  force = false
) {
  if (
    state.appointmentTemplatesLoaded &&
    !force
  ) {
    return state.appointmentTemplates;
  }

  try {
    const response =
      await fetch(
        "/api/appointment-templates",
        {
          credentials: "include",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json =
        text
          ? JSON.parse(text)
          : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "loadAppointmentTemplatesApi failed:",
        response.status,
        text
      );

      return [];
    }

    const templates =
      Array.isArray(json.data)
        ? json.data
        : [];

    state.appointmentTemplates =
      templates;

    state.appointmentTemplatesLoaded =
      true;

    return templates;

  } catch (error) {
    console.error(
      "loadAppointmentTemplatesApi error:",
      error
    );

    return [];
  }
}

async function createAppointmentTemplateApi(
  payload
) {
  try {
    const response =
      await fetch(
        "/api/appointment-templates",
        {
          method: "POST",

          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify(
              payload || {}
            ),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json =
        text
          ? JSON.parse(text)
          : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "createAppointmentTemplateApi failed:",
        response.status,
        text
      );

      throw new Error(
        json?.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё С€Р°Р±Р»РѕРЅ."
      );
    }

    return Array.isArray(
      json.data
    )
      ? json.data[0] || null
      : json.data || null;

  } catch (error) {
    console.error(
      "createAppointmentTemplateApi error:",
      error
    );

    throw error;
  }
}
