async function createPatientApi(payload) {
  try {
    const bodyObj = {
  owner_id:
    payload?.owner_id,

  name:
    String(
      payload?.name || ""
    ).trim(),

  species:
    String(
      payload?.species || ""
    ).trim(),

  breed:
    String(
      payload?.breed || ""
    ).trim(),

  age:
    String(
      payload?.age || ""
    ).trim(),

  weight_kg:
    String(
      payload?.weight_kg || ""
    ).trim(),

  sex:
    String(
      payload?.sex || ""
    ).trim(),

  neutered:
  typeof payload?.neutered ===
    "boolean"
    ? payload.neutered
    : null,


rabies_status:
  String(
    payload?.rabies_status ||
    "unknown"
  ).trim(),


general_vaccination_status:
  String(
    payload?.general_vaccination_status ||
    "unknown"
  ).trim(),


// РЎС‚Р°СЂС‹Рµ РїРѕР»СЏ РїРѕРєР° РѕСЃС‚Р°РІР»СЏРµРј
// РґРѕ РїРѕР»РЅРѕРіРѕ РїРµСЂРµС…РѕРґР° С„РѕСЂРј.

vaccination_status:
  String(
    payload?.vaccination_status ||
    "unknown"
  ).trim(),

vaccination_date:
  String(
    payload?.vaccination_date ||
    ""
  ).trim(),

vaccination_name:
  String(
    payload?.vaccination_name ||
    ""
  ).trim(),


notes:
    String(
      payload?.notes ||
      payload?.note ||
      ""
    ).trim(),
};

    Object.keys(bodyObj).forEach((k) => {
      if (bodyObj[k] === "" || bodyObj[k] == null) delete bodyObj[k];
    });

    const res = await fetch("/api/patients", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...getOrgHeaders() },
      credentials: "include",
      body: JSON.stringify(bodyObj),
    });

    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok) {
      console.error("API /patients POST HTTP", res.status, text);
      alert(`РџРѕРјРёР»РєР° СЃРµСЂРІРµСЂР° РїСЂРё СЃС‚РІРѕСЂРµРЅРЅС– РїР°С†С–С”РЅС‚Р° (HTTP ${res.status})`);
      return null;
    }

    if (!json || !json.ok) {
      console.error("API /patients POST bad json", json, text);
      alert(json?.error || "РџРѕРјРёР»РєР° СЃС‚РІРѕСЂРµРЅРЅСЏ РїР°С†С–С”РЅС‚Р°");
      return null;
    }

    const created = Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
    if (!created) return null;

    const next = [created, ...(Array.isArray(state.patients) ? state.patients : [])]
      .filter((x, i, a) => i === a.findIndex((y) => String(y?.id) === String(x?.id)));

    state.patients = next;
    savePatients(next);
    return created;
  } catch (err) {
    console.error("createPatientApi failed:", err);
    alert("РџРѕРјРёР»РєР° Р·КјС”РґРЅР°РЅРЅСЏ Р· СЃРµСЂРІРµСЂРѕРј");
    return null;
  }
}
async function loadPatientWeightsApi(
  patientId,
  retry = true
) {
  try {
    const response =
      await fetch(
        `/api/patients/${
          encodeURIComponent(
            String(patientId)
          )
        }/weights`,
        {
          credentials:
            "include",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );

    const result =
      await response
        .json()
        .catch(() => null);

    if (
      !response.ok ||
      !result?.ok
    ) {
      throw new Error(
        result?.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё С–СЃС‚РѕСЂС–СЋ РІР°РіРё."
      );
    }

    return Array.isArray(
      result.data
    )
      ? result.data
      : [];

  } catch (error) {

    if (retry) {
      await new Promise(
        (resolve) =>
          setTimeout(
            resolve,
            350
          )
      );

      return loadPatientWeightsApi(
        patientId,
        false
      );
    }

    throw error;
  }
}


