async function updateVisitApi(
  visitId,
  payload
) {
  try {
    const cleanVisitId =
      String(
        visitId || ""
      ).trim();

    if (!cleanVisitId) {
      console.error(
        "updateVisitApi: visitId is required"
      );

      return null;
    }

    const url =
      `/api/visits?id=${encodeURIComponent(
        cleanVisitId
      )}`;

    const response =
      await fetch(
        url,
        {
          method: "PUT",
          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify(
              payload || {}
            ),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {
      json = null;
    }

    if (!response.ok) {
      console.error(
        "updateVisitApi HTTP error:",
        response.status,
        text
      );

      alert(
        json?.error ||
        `API error ${response.status}`
      );

      return null;
    }

    if (
      !json ||
      typeof json !== "object"
    ) {
      console.error(
        "updateVisitApi: server returned non-JSON:",
        text
      );

      alert(
        "РЎРµСЂРІРµСЂ РїРѕРІРµСЂРЅСѓРІ РЅРµРєРѕСЂРµРєС‚РЅСѓ РІС–РґРїРѕРІС–РґСЊ."
      );

      return null;
    }

    if (json.ok !== true) {
      console.error(
        "updateVisitApi: json.ok=false:",
        json
      );

      alert(
        json.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ РѕРЅРѕРІРёС‚Рё РІС–Р·РёС‚."
      );

      return null;
    }

    const raw =
      Array.isArray(json.data)
        ? json.data[0] || null
        : json.data || null;

    let updated =
      normalizeVisitFromServer(
        raw
      );

    if (
      !updated ||
      updated.id == null
    ) {
      console.warn(
        "updateVisitApi: updated visit has no id:",
        updated,
        json
      );

      return updated || null;
    }

    const normalizedVisitId =
      String(updated.id);

    const previousVisit =
      state.visitsById.get(
        normalizedVisitId
      ) || null;

    if (previousVisit) {
      const previousServices =
        Array.isArray(
          previousVisit.services
        )
          ? previousVisit.services
          : [];

      const previousStock =
        Array.isArray(
          previousVisit.stock
        )
          ? previousVisit.stock
          : [];

      const updatedHasServices =
        Array.isArray(
          updated.services
        );

      const updatedHasStock =
        Array.isArray(
          updated.stock
        );

      if (
        !updatedHasServices &&
        previousServices.length
      ) {
        updated.services =
          previousServices;

        updated.services_json =
          previousServices;
      }

      if (
        !updatedHasStock &&
        previousStock.length
      ) {
        updated.stock =
          previousStock;

        updated.stock_json =
          previousStock;
      }
    }

    cacheVisits([
      updated,
    ]);

    return updated;

  } catch (error) {
    console.error(
      "updateVisitApi failed:",
      error
    );

    alert(
      "РџРѕРјРёР»РєР° Р·КјС”РґРЅР°РЅРЅСЏ Р· СЃРµСЂРІРµСЂРѕРј."
    );

    return null;
  }
}
async function completeVisitApi(
  visitId
) {
  const cleanVisitId =
    String(
      visitId || ""
    ).trim();

  if (!cleanVisitId) {
    throw new Error(
      "РќРµ РІРєР°Р·Р°РЅРѕ ID РІС–Р·РёС‚Сѓ."
    );
  }

  const response =
    await fetch(
      `/api/visits/${
        encodeURIComponent(
          cleanVisitId
        )
      }/complete`,
      {
        method: "POST",

        credentials:
          "include",

        headers: {
          Accept:
            "application/json",

          ...getOrgHeaders(),
        },
      }
    );

  const text =
    await response.text();

  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {
    json = null;
  }

  if (
    response.status === 409
  ) {
    throw new Error(
      json?.error ||
      "Р’С–Р·РёС‚ СѓР¶Рµ Р·Р°РІРµСЂС€РµРЅРѕ."
    );
  }

  if (
    !response.ok ||
    !json ||
    json.ok !== true
  ) {
    console.error(
      "completeVisitApi failed:",
      response.status,
      text
    );

    throw new Error(
      json?.error ||
      (
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІРµСЂС€РёС‚Рё РІС–Р·РёС‚. " +
        `HTTP ${response.status}.`
      )
    );
  }

  const completedVisit =
    Array.isArray(
      json.data
    )
      ? json.data[0] || null
      : json.data || null;

  if (!completedVisit?.id) {
    throw new Error(
      "РЎРµСЂРІРµСЂ РЅРµ РїРѕРІРµСЂРЅСѓРІ Р·Р°РІРµСЂС€РµРЅРёР№ РІС–Р·РёС‚."
    );
  }

  const normalizedVisit =
    normalizeVisitFromServer(
      completedVisit
    );

  cacheVisits([
    normalizedVisit,
  ]);

  return normalizedVisit;
}
