async function removeStockLineFromVisit(
  visitId,
  index
) {
  return enqueueVisitMutation(
    visitId,
    () => removeStockLineFromVisitNow(
      visitId,
      index
    )
  );
}


async function removeStockLineFromVisitNow(
  visitId,
  index
) {
  if (!visitId) {
    return false;
  }

  const vid =
    String(visitId);

  const current =
    getVisitByIdSync(vid) ||
    await fetchVisitById(vid);

  if (!current) {
    throw new Error(
      "Р’С–Р·РёС‚ РЅРµ Р·РЅР°Р№РґРµРЅРѕ."
    );
  }

  ensureVisitStockShape(
    current
  );

  const itemIndex =
    Number(index);

  if (
    !Number.isFinite(
      itemIndex
    ) ||
    itemIndex < 0 ||
    itemIndex >=
      current.stock.length
  ) {
    return false;
  }

  const line =
    current.stock[
      itemIndex
    ];

  const lineId =
    String(
      line?.id || ""
    ).trim();

  if (!lineId) {
    throw new Error(
      "РћРЅРѕРІС–С‚СЊ СЃС‚РѕСЂС–РЅРєСѓ С‚Р° РїРѕРІС‚РѕСЂС–С‚СЊ РІРёРґР°Р»РµРЅРЅСЏ."
    );
  }

  const data =
    await stockApiRequest(
      `/api/visits/${encodeURIComponent(
        vid
      )}/stock/${encodeURIComponent(
        lineId
      )}`,
      {
        method: "DELETE",
      }
    );

  const nextStock =
    current.stock.slice();

  nextStock.splice(
    itemIndex,
    1
  );

  current.stock =
    nextStock;

  current.stock_json =
    nextStock;

  state.visitsById.set(
    vid,
    current
  );

  if (
    String(
      state.selectedVisitId
    ) === vid
  ) {
    state.selectedVisit =
      current;
  }

  if (data?.stock) {
    const updatedStock =
      normalizeStockItem(
        data.stock
      );

    state.stock =
      loadStock().map(
        (item) =>
          String(item.id) ===
          String(updatedStock.id)
            ? updatedStock
            : item
      );

    state.stockLoaded = true;
  }

  return true;
}

function expandStockLines(visit) {
  const lines = Array.isArray(visit?.stock) ? visit.stock : [];
  return lines
    .filter((line) => line && (line.stockId || line.stock_id))
    .map((line) => {
      const stockId = line.stockId || line.stock_id;
      const it = getStockById(stockId);

      const name = String(line.nameSnap ?? line.name_snap ?? it?.name ?? "РќРµРІС–РґРѕРјР° РїРѕР·РёС†С–СЏ").trim();
      const unit = String(line.unitSnap ?? line.unit_snap ?? it?.unit ?? "С€С‚").trim();
      const price = Number(line.priceSnap ?? line.price_snap ?? it?.price ?? it?.price_uah ?? it?.sell_price ?? it?.sale_price ?? it?.cost ?? 0) || 0;
      const qty = Math.max(1, Number(line.qty ?? line.quantity ?? 1) || 1);
      const lineTotal = price * qty;

      return { name, unit, price, qty, lineTotal };
    });
}

function calcStockTotal(visit) {
  return expandStockLines(visit).reduce((sum, x) => sum + (Number(x?.lineTotal) || 0), 0);
}

function captureVisitMedicalDraft(
  visitId =
    state.selectedVisitId
) {
  const complaint =
    document.getElementById(
      "visitMedComplaint"
    );

  const diagnosis =
    document.getElementById(
      "visitMedDx"
    );

  const treatment =
    document.getElementById(
      "visitMedRx"
    );

  const recommendation =
    document.getElementById(
      "visitClientRecommendation"
    );

  const weight =
    document.getElementById(
      "visitWeightDisplay"
    );

  if (
    !complaint &&
    !diagnosis &&
    !treatment &&
    !recommendation &&
    !weight
  ) {
    return null;
  }

  return {
    visitId:
      String(visitId || ""),

    complaint:
      complaint?.value ?? "",

    diagnosis:
      diagnosis?.value ?? "",

    treatment:
      treatment?.value ?? "",

    recommendation:
      recommendation?.value ?? "",

    weight:
      weight?.value ?? "",
  };
}

function restoreVisitMedicalDraft(
  draft,
  visitId =
    state.selectedVisitId
) {
  if (
    !draft ||
    String(draft.visitId || "") !==
      String(visitId || "")
  ) {
    return;
  }

  const fields = [
    [
      "visitMedComplaint",
      draft.complaint,
    ],
    [
      "visitMedDx",
      draft.diagnosis,
    ],
    [
      "visitMedRx",
      draft.treatment,
    ],
    [
      "visitClientRecommendation",
      draft.recommendation,
    ],
    [
      "visitWeightDisplay",
      draft.weight,
    ],
  ];

  fields.forEach(
    ([fieldId, value]) => {
      const field =
        document.getElementById(
          fieldId
        );

      if (field) {
        field.value =
          value ?? "";
      }
    }
  );
}

function renderVisitPagePreservingMedicalDraft(
  visit,
  pet
) {
  const visitId =
    String(
      visit?.id ||
      state.selectedVisitId ||
      ""
    );

  const draft =
    captureVisitMedicalDraft(
      visitId
    );

  renderVisitPage(
    visit,
    pet
  );

  restoreVisitMedicalDraft(
    draft,
    visitId
  );
}

async function refreshVisitUIIfOpen() {
  if (state.route !== "visit" || !state.selectedVisitId) return;

  let v = getVisitByIdSync(state.selectedVisitId);
  if (!v) v = await fetchVisitById(state.selectedVisitId);
  if (!v) return;

  const pet = state.selectedPet || loadPatients().find((p) => p.id === v.pet_id) || null;
  renderVisitPagePreservingMedicalDraft(
    v,
    pet
  );
  renderDischargeA4(state.selectedVisitId);
}

