function getServiceCategoryIcon(category) {
  const value =
    String(category || "")
      .trim()
      .toLowerCase();

  if (
    value.includes("С‚РµСЂР°Рї")
  ) {
    return "рџ©є";
  }

  if (
    value.includes("Р°РЅР°Р»")
  ) {
    return "рџ§Є";
  }

  if (
    value.includes("С…С–СЂСѓ") ||
    value.includes("С…РёСЂСѓСЂРі")
  ) {
    return "вњ‚пёЏ";
  }

  if (
    value.includes("РґС–Р°Рі") ||
    value.includes("РґРёР°Рі")
  ) {
    return "рџ”¬";
  }

  if (
    value.includes("РІРёС—Р·Рґ") ||
    value.includes("РІС‹РµР·Рґ")
  ) {
    return "рџљ‘";
  }

  if (
    value.includes("РІР°РєС†РёРЅ")
  ) {
    return "рџ’‰";
  }

  if (
    value.includes("СЃС‚РѕРјР°С‚")
  ) {
    return "рџ¦·";
  }

  if (
    value.includes("СЃС‚Р°С†С–РѕРЅ") ||
    value.includes("СЃС‚Р°С†РёРѕРЅ")
  ) {
    return "рџЏҐ";
  }

  return "вњЁ";
}


function getServiceCategoryColor(
  category
) {
  const value =
    String(category || "")
      .trim()
      .toLowerCase();

  if (value.includes("С‚РµСЂР°Рї")) {
    return "#7c5cff";
  }

  if (value.includes("Р°РЅР°Р»")) {
    return "#36c7ff";
  }

  if (
    value.includes("С…С–СЂСѓ") ||
    value.includes("С…РёСЂСѓСЂРі")
  ) {
    return "#ff6685";
  }

  if (
    value.includes("РґС–Р°Рі") ||
    value.includes("РґРёР°Рі")
  ) {
    return "#51df9c";
  }

  if (
    value.includes("РІРёС—Р·Рґ") ||
    value.includes("РІС‹РµР·Рґ")
  ) {
    return "#ffb84d";
  }

  if (value.includes("РІР°РєС†РёРЅ")) {
    return "#c06cff";
  }

  return "#9f67ff";
}


function getServiceCategories(
  services
) {
  const categories =
    Array.from(
      new Set(
        (services || [])
          .map((service) =>
            String(
              service?.cat ||
              "Р†РЅС€Рµ"
            ).trim()
          )
          .filter(Boolean)
      )
    );

  const preferredOrder = [
    "РўРµСЂР°РїС–СЏ",
    "РђРЅР°Р»С–Р·Рё",
    "РҐС–СЂСѓСЂРіС–СЏ",
    "Р”С–Р°РіРЅРѕСЃС‚РёРєР°",
    "Р’Р°РєС†РёРЅР°С†С–СЏ",
    "РЎС‚РѕРјР°С‚РѕР»РѕРіС–СЏ",
    "РЎС‚Р°С†С–РѕРЅР°СЂ",
    "Р’РёС—Р·Рґ",
    "Р†РЅС€Рµ",
  ];

  return categories.sort(
    (a, b) => {
      const indexA =
        preferredOrder.indexOf(a);

      const indexB =
        preferredOrder.indexOf(b);

      return (
        (
          indexA === -1
            ? 999
            : indexA
        ) -
        (
          indexB === -1
            ? 999
            : indexB
        )
      );
    }
  );
}


