function openServiceEditorModal(
  service = null
) {
  document
    .getElementById(
      "serviceEditorModal"
    )
    ?.remove();

  const isEdit =
    Boolean(service?.id);

  const modal =
    document.createElement("div");

  modal.id =
    "serviceEditorModal";

  modal.className =
    "serviceEditorOverlay";

  const categories = [
    "РўРµСЂР°РїС–СЏ",
    "РђРЅР°Р»С–Р·Рё",
    "РҐС–СЂСѓСЂРіС–СЏ",
    "Р”С–Р°РіРЅРѕСЃС‚РёРєР°",
    "Р’Р°РєС†РёРЅР°С†С–СЏ",
    "РЎС‚РѕРјР°С‚РѕР»РѕРіС–СЏ",
    "РЎС‚Р°С†С–РѕРЅР°СЂ",
    "Р’РёС—Р·Рґ",
    "Р†РЅС€Рµ",
  ];

  const selectedCategory =
    String(
      service?.cat ||
      "РўРµСЂР°РїС–СЏ"
    );

  modal.innerHTML = `
    <div
      class="serviceEditorBackdrop"
      data-close-service-editor
    ></div>

    <section
      class="serviceEditorModal"
      role="dialog"
      aria-modal="true"
    >
      <button
        class="serviceEditorClose"
        type="button"
        data-close-service-editor
      >
        вњ•
      </button>

      <header class="serviceEditorHeader">
        <div class="serviceEditorIcon">
          ${
            isEdit
              ? "вњЋ"
              : "пј‹"
          }
        </div>

        <div>
          <div class="serviceEditorEyebrow">
            ${
              isEdit
                ? "Р Р•Р”РђР“РЈР’РђРќРќРЇ РџРћРЎР›РЈР“Р"
                : "РќРћР’Рђ РџРћРЎР›РЈР“Рђ"
            }
          </div>

          <h2>
            ${
              isEdit
                ? "РћРЅРѕРІРёС‚Рё РїРѕСЃР»СѓРіСѓ"
                : "Р”РѕРґР°С‚Рё Сѓ РєР°С‚Р°Р»РѕРі"
            }
          </h2>

          <p>
            РќР°Р·РІР°, РєР°С‚РµРіРѕСЂС–СЏ С‚Р° С†С–РЅР°
            Р±СѓРґСѓС‚СЊ РґРѕСЃС‚СѓРїРЅС– РїС–Рґ С‡Р°СЃ
            СЃС‚РІРѕСЂРµРЅРЅСЏ РІС–Р·РёС‚Сѓ.
          </p>
        </div>
      </header>

      <form
        id="serviceEditorForm"
        class="serviceEditorForm"
      >
        <label class="serviceEditorField">
          <span>
            РќР°Р·РІР° РїРѕСЃР»СѓРіРё
          </span>

          <input
            id="serviceEditorName"
            type="text"
            placeholder="РќР°РїСЂРёРєР»Р°Рґ, РџРµСЂРІРёРЅРЅРёР№ РѕРіР»СЏРґ"
            value="${escapeHtml(
              service?.name || ""
            )}"
            autocomplete="off"
          >
        </label>

        <div class="serviceEditorFieldsRow">
          <label class="serviceEditorField">
            <span>
              РљР°С‚РµРіРѕСЂС–СЏ
            </span>

            <select
              id="serviceEditorCategory"
            >
              ${categories
                .map(
                  (category) => `
                    <option
                      value="${escapeHtml(
                        category
                      )}"
                      ${
                        selectedCategory ===
                        category
                          ? "selected"
                          : ""
                      }
                    >
                      ${escapeHtml(
                        category
                      )}
                    </option>
                  `
                )
                .join("")}
            </select>
          </label>

          <label class="serviceEditorField">
            <span>
              Р¦С–РЅР°, РіСЂРЅ
            </span>

            <input
              id="serviceEditorPrice"
              type="number"
              min="0"
              step="1"
              placeholder="0"
              value="${escapeHtml(
                String(
                  service?.price ??
                  ""
                )
              )}"
            >
          </label>
        </div>

        <label class="serviceEditorStatus">
          <div>
            <strong>
              РђРєС‚РёРІРЅР° РїРѕСЃР»СѓРіР°
            </strong>

            <span>
              Р”РѕСЃС‚СѓРїРЅР° РґР»СЏ РґРѕРґР°РІР°РЅРЅСЏ
              Сѓ РІС–Р·РёС‚
            </span>
          </div>

          <label class="servicesPremiumSwitch serviceEditorSwitch">
            <input
              id="serviceEditorActive"
              type="checkbox"
              ${
                service?.active === false
                  ? ""
                  : "checked"
              }
            >

            <span></span>
          </label>
        </label>

        <div class="serviceEditorPreview">
          <div
            class="serviceEditorPreviewIcon"
            id="serviceEditorPreviewIcon"
          >
            ${getServiceCategoryIcon(
              selectedCategory
            )}
          </div>

          <div>
            <span>
              РџРѕРїРµСЂРµРґРЅС–Р№ РїРµСЂРµРіР»СЏРґ
            </span>

            <strong
              id="serviceEditorPreviewName"
            >
              ${escapeHtml(
                service?.name ||
                "РќР°Р·РІР° РїРѕСЃР»СѓРіРё"
              )}
            </strong>

            <small>
              <b
                id="serviceEditorPreviewCategory"
              >
                ${escapeHtml(
                  selectedCategory
                )}
              </b>

              В·

              <em
                id="serviceEditorPreviewPrice"
              >
                ${Number(
                  service?.price || 0
                ).toLocaleString(
                  "uk-UA"
                )}
                РіСЂРЅ
              </em>
            </small>
          </div>
        </div>

        <footer class="serviceEditorActions">
          <button
            class="serviceEditorCancel"
            type="button"
            data-close-service-editor
          >
            РЎРєР°СЃСѓРІР°С‚Рё
          </button>

          <button
            class="serviceEditorSubmit"
            id="serviceEditorSubmit"
            type="submit"
          >
            ${
              isEdit
                ? "Р—Р±РµСЂРµРіС‚Рё Р·РјС–РЅРё"
                : "Р”РѕРґР°С‚Рё РїРѕСЃР»СѓРіСѓ"
            }
          </button>
        </footer>
      </form>
    </section>
  `;

  document.body.appendChild(
    modal
  );

  const closeModal = () => {
    modal.remove();
  };

  modal.addEventListener(
    "click",
    (event) => {
      if (
        event.target.closest(
          "[data-close-service-editor]"
        )
      ) {
        closeModal();
      }
    }
  );

  const nameInput =
    modal.querySelector(
      "#serviceEditorName"
    );

  const categoryInput =
    modal.querySelector(
      "#serviceEditorCategory"
    );

  const priceInput =
    modal.querySelector(
      "#serviceEditorPrice"
    );

  const updatePreview = () => {
    const name =
      String(
        nameInput?.value || ""
      ).trim();

    const category =
      String(
        categoryInput?.value ||
        "Р†РЅС€Рµ"
      );

    const price =
      Number(
        priceInput?.value || 0
      );

    const previewIcon =
      modal.querySelector(
        "#serviceEditorPreviewIcon"
      );

    const previewName =
      modal.querySelector(
        "#serviceEditorPreviewName"
      );

    const previewCategory =
      modal.querySelector(
        "#serviceEditorPreviewCategory"
      );

    const previewPrice =
      modal.querySelector(
        "#serviceEditorPreviewPrice"
      );

    if (previewIcon) {
      previewIcon.textContent =
        getServiceCategoryIcon(
          category
        );
    }

    if (previewName) {
      previewName.textContent =
        name ||
        "РќР°Р·РІР° РїРѕСЃР»СѓРіРё";
    }

    if (previewCategory) {
      previewCategory.textContent =
        category;
    }

    if (previewPrice) {
      previewPrice.textContent =
        `${price.toLocaleString(
          "uk-UA"
        )} РіСЂРЅ`;
    }
  };

  nameInput?.addEventListener(
    "input",
    updatePreview
  );

  categoryInput?.addEventListener(
    "change",
    updatePreview
  );

  priceInput?.addEventListener(
    "input",
    updatePreview
  );

  modal
    .querySelector(
      "#serviceEditorForm"
    )
    ?.addEventListener(
      "submit",
      async (event) => {
        event.preventDefault();

        const name =
          String(
            nameInput?.value || ""
          ).trim();

        const category =
          String(
            categoryInput?.value ||
            "Р†РЅС€Рµ"
          ).trim();

        const price =
          Math.max(
            0,
            Number(
              priceInput?.value || 0
            )
          );

        const active =
          modal.querySelector(
            "#serviceEditorActive"
          )?.checked !== false;

        if (!name) {
          alert(
            "Р’РєР°Р¶С–С‚СЊ РЅР°Р·РІСѓ РїРѕСЃР»СѓРіРё."
          );

          nameInput?.focus();
          return;
        }

        const submitButton =
          modal.querySelector(
            "#serviceEditorSubmit"
          );

        if (submitButton) {
          submitButton.disabled =
            true;

          submitButton.textContent =
            "Р—Р±РµСЂРµР¶РµРЅРЅСЏвЂ¦";
        }

        let saved = null;

        if (isEdit) {
          saved =
            await updateServiceApi(
              service.id,
              {
                name,
                price,
                active,
                cat:
                  category,
              }
            );
        } else {
          saved =
            await createServiceApi({
              name,
              price,
              active,
              cat:
                category,
            });
        }

        if (!saved) {
          if (submitButton) {
            submitButton.disabled =
              false;

            submitButton.textContent =
              isEdit
                ? "Р—Р±РµСЂРµРіС‚Рё Р·РјС–РЅРё"
                : "Р”РѕРґР°С‚Рё РїРѕСЃР»СѓРіСѓ";
          }

          alert(
            "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р±РµСЂРµРіС‚Рё РїРѕСЃР»СѓРіСѓ."
          );

          return;
        }

        saveServiceCatToMap(
          saved.id ||
          service?.id,
          category
        );

        closeModal();

        await loadServicesApi();
        await renderServicesTab();
      }
    );

  setTimeout(() => {
    nameInput?.focus();
  }, 60);
}


