function openServiceDeleteConfirm(
  service
) {
  return new Promise(
    (resolve) => {
      document
        .getElementById(
          "serviceDeleteConfirm"
        )
        ?.remove();

      const modal =
        document.createElement(
          "div"
        );

      modal.id =
        "serviceDeleteConfirm";

      modal.className =
        "serviceDeleteOverlay";

      modal.innerHTML = `
        <div
          class="serviceDeleteBackdrop"
          data-service-delete-cancel
        ></div>

        <section class="serviceDeleteModal">
          <div class="serviceDeleteIcon">
            рџ—‘
          </div>

          <div class="serviceDeleteEyebrow">
            Р’РР”РђР›Р•РќРќРЇ РџРћРЎР›РЈР“Р
          </div>

          <h2>
            Р’РёРґР°Р»РёС‚Рё РїРѕСЃР»СѓРіСѓ?
          </h2>

          <p>
            РџРѕСЃР»СѓРіР° Р±С–Р»СЊС€Рµ РЅРµ Р±СѓРґРµ
            РґРѕСЃС‚СѓРїРЅР° Сѓ РєР°С‚Р°Р»РѕР·С– РєР»С–РЅС–РєРё.
          </p>

          <div class="serviceDeleteService">
            <span>
              ${getServiceCategoryIcon(
                service?.cat
              )}
            </span>

            <div>
              <strong>
                ${escapeHtml(
                  service?.name ||
                  "РџРѕСЃР»СѓРіР°"
                )}
              </strong>

              <small>
                ${escapeHtml(
                  service?.cat ||
                  "Р†РЅС€Рµ"
                )}
                В·
                ${Number(
                  service?.price || 0
                ).toLocaleString(
                  "uk-UA"
                )}
                РіСЂРЅ
              </small>
            </div>
          </div>

          <div class="serviceDeleteActions">
            <button
              type="button"
              class="serviceDeleteCancel"
              data-service-delete-cancel
            >
              РЎРєР°СЃСѓРІР°С‚Рё
            </button>

            <button
              type="button"
              class="serviceDeleteSubmit"
              id="serviceDeleteSubmit"
            >
              Р’РёРґР°Р»РёС‚Рё
            </button>
          </div>
        </section>
      `;

      document.body.appendChild(
        modal
      );

      const finish = (
        result
      ) => {
        modal.remove();
        resolve(result);
      };

      modal.addEventListener(
        "click",
        (event) => {
          if (
            event.target.closest(
              "[data-service-delete-cancel]"
            )
          ) {
            finish(false);
          }
        }
      );

      modal
        .querySelector(
          "#serviceDeleteSubmit"
        )
        ?.addEventListener(
          "click",
          () => {
            finish(true);
          }
        );
    }
  );
}





function openSpecializationCreateModal() {
  return new Promise((resolve) => {
    const themeColors = {
      purple: "#A855F7",
      black: "#F43F5E",
      white: "#5856D6",
      blue: "#06B6D4",
      green: "#10B981",
    };

    const activeTheme =
      document.body.dataset.theme ||
      "purple";

    const modal =
      document.createElement("div");

    modal.className =
      "specializationEditorOverlay";

    modal.innerHTML = `
      <button
        class="specializationEditorBackdrop"
        type="button"
        aria-label="Р—Р°РєСЂРёС‚Рё"
        data-specialization-cancel
      ></button>

      <section
        class="specializationEditorModal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="specializationEditorTitle"
      >
        <button
          class="specializationEditorClose"
          type="button"
          aria-label="Р—Р°РєСЂРёС‚Рё"
          data-specialization-cancel
        >
          Г—
        </button>

        <div class="specializationEditorHeader">
          <div class="specializationEditorIcon">вњ¦</div>

          <div>
            <div class="specializationEditorEyebrow">
              РќРћР’РР™ РќРђРџР РЇРњ
            </div>

            <h2 id="specializationEditorTitle">
              Р”РѕРґР°С‚Рё РЅР°РїСЂСЏРј
            </h2>

            <p>
              РЎС‚РІРѕСЂС–С‚СЊ РЅР°РїСЂСЏРј РєР»С–РЅС–РєРё РґР»СЏ С„С–Р»СЊС‚СЂР°С†С–С—
              СЃРїС–РІСЂРѕР±С–С‚РЅРёРєС–РІ С– СЃРїРµС†С–Р°Р»С–Р·Р°С†С–Р№.
            </p>
          </div>
        </div>

        <form class="specializationEditorForm">
          <label class="specializationEditorField">
            <span>РќР°Р·РІР° РЅР°РїСЂСЏРјСѓ</span>
            <input
              id="specializationEditorName"
              type="text"
              maxlength="80"
              autocomplete="off"
              placeholder="РќР°РїСЂРёРєР»Р°Рґ, РҐС–СЂСѓСЂРіС–СЏ"
              required
            >
          </label>

          <label class="specializationEditorColorField">
            <span>
              <strong>РљРѕР»С–СЂ РЅР°РїСЂСЏРјСѓ</strong>
              <small>Р’РёРєРѕСЂРёСЃС‚РѕРІСѓС”С‚СЊСЃСЏ Сѓ СЃРїРёСЃРєР°С… С– РїСЂРѕС„С–Р»СЏС…</small>
            </span>

            <input
              id="specializationEditorColor"
              type="color"
              value="${themeColors[activeTheme] || themeColors.purple}"
            >
          </label>

          <div
            class="specializationEditorError"
            role="alert"
            aria-live="polite"
          ></div>

          <div class="specializationEditorActions">
            <button
              class="specializationEditorCancel"
              type="button"
              data-specialization-cancel
            >
              РЎРєР°СЃСѓРІР°С‚Рё
            </button>

            <button
              class="specializationEditorSubmit"
              type="submit"
            >
              Р”РѕРґР°С‚Рё РЅР°РїСЂСЏРј
            </button>
          </div>
        </form>
      </section>
    `;

    document.body.appendChild(modal);

    const input = modal.querySelector(
      "#specializationEditorName"
    );

    const colorInput = modal.querySelector(
      "#specializationEditorColor"
    );

    const errorBox = modal.querySelector(
      ".specializationEditorError"
    );

    let finished = false;

    const finish = (result) => {
      if (finished) return;
      finished = true;
      document.removeEventListener(
        "keydown",
        handleKeydown
      );
      modal.remove();
      resolve(result);
    };

    const handleKeydown = (event) => {
      if (event.key === "Escape") {
        finish(null);
      }
    };

    document.addEventListener(
      "keydown",
      handleKeydown
    );

    modal
      .querySelectorAll(
        "[data-specialization-cancel]"
      )
      .forEach((button) => {
        button.addEventListener(
          "click",
          () => finish(null)
        );
      });

    modal
      .querySelector(
        ".specializationEditorForm"
      )
      ?.addEventListener(
        "submit",
        (event) => {
          event.preventDefault();

          const name = String(
            input?.value || ""
          ).trim();

          if (!name) {
            if (errorBox) {
              errorBox.textContent =
                "Р’РєР°Р¶С–С‚СЊ РЅР°Р·РІСѓ РЅР°РїСЂСЏРјСѓ.";
            }

            input?.focus();
            return;
          }

          finish({
            name,
            color:
              colorInput?.value ||
              themeColors.purple,
          });
        }
      );

    requestAnimationFrame(() => {
      input?.focus();
    });
  });
}

function getStaffSpecializations(staffRow) {
  return Array.isArray(
    staffRow?.specializations
  )
    ? staffRow.specializations.filter(
        (item) => item?.id && item?.name
      )
    : [];
}

function renderStaffSpecializationTags(
  staffRow,
  className = "premiumSpecTag"
) {
  const specializations =
    getStaffSpecializations(staffRow);

  if (specializations.length) {
    return specializations
      .map(
        (specialization) => `
          <span
            class="${escapeHtml(className)}"
            style="
              --specialization-color:
                ${escapeHtml(
                  specialization.color ||
                  "#7C5CFF"
                )};
            "
          >
            ${escapeHtml(
              specialization.name
            )}
          </span>
        `
      )
      .join("");
  }

  return `
    <span class="${escapeHtml(className)} is-empty">
      ${escapeHtml(
        staffRow?.specialization ||
        "РќР°РїСЂСЏРј РЅРµ РІРєР°Р·Р°РЅРѕ"
      )}
    </span>
  `;
}

function getStaffContrastColor(color) {
  const value = String(
    color || ""
  ).trim();

  let red = 124;
  let green = 92;
  let blue = 255;

  const shortHex =
    value.match(
      /^#([0-9a-f]{3})$/i
    );
  const fullHex =
    value.match(
      /^#([0-9a-f]{6})$/i
    );
  const rgbColor =
    value.match(
      /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i
    );

  if (shortHex) {
    red = parseInt(
      shortHex[1][0] +
      shortHex[1][0],
      16
    );
    green = parseInt(
      shortHex[1][1] +
      shortHex[1][1],
      16
    );
    blue = parseInt(
      shortHex[1][2] +
      shortHex[1][2],
      16
    );
  } else if (fullHex) {
    red = parseInt(
      fullHex[1].slice(0, 2),
      16
    );
    green = parseInt(
      fullHex[1].slice(2, 4),
      16
    );
    blue = parseInt(
      fullHex[1].slice(4, 6),
      16
    );
  } else if (rgbColor) {
    red = Number(rgbColor[1]);
    green = Number(rgbColor[2]);
    blue = Number(rgbColor[3]);
  } else {
    return "#6f91ad";
  }

  const luminance =
    (
      red * 0.2126 +
      green * 0.7152 +
      blue * 0.0722
    ) / 255;
  const chroma =
    Math.max(red, green, blue) -
    Math.min(red, green, blue);

  if (
    luminance > 0.82 &&
    chroma < 28
  ) {
    return "#6f91ad";
  }

  if (luminance > 0.7) {
    const darken = (channel) =>
      Math.max(
        0,
        Math.min(
          255,
          Math.round(
            channel * 0.62
          )
        )
      )
        .toString(16)
        .padStart(2, "0");

    return `#${darken(red)}${darken(green)}${darken(blue)}`;
  }

  return value;
}
