function getStaffSkills(doc) {
  const raw = doc?.skills;

  if (Array.isArray(raw)) return raw;

  if (typeof raw === "string") {
    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return raw
        .split(",")
        .map((x) => x.trim())
        .filter(Boolean);
    }
  }

  return [];
}

function renderStaffSkillsPanel(doc) {
  const skills = getStaffSkills(doc);

  return `
    <div class="teamDashPanel staffSkillsPanel">
      <div class="teamDashPanelHead">
        <h3>рџ§  РќР°РІРёС‡РєРё</h3>
        <button class="teamGhostBtn mini" id="btnAddStaffSkill" type="button">
          + Р”РѕРґР°С‚Рё
        </button>
      </div>

      <div class="staffSkillsCards" id="staffSkillsList">
        ${
          skills.length
            ? skills.map((skill) => renderStaffSkillCard(skill)).join("")
            : `<p class="hint">РќР°РІРёС‡РєРё С‰Рµ РЅРµ РґРѕРґР°РЅС–. РќР°РїСЂРёРєР»Р°Рґ: РЈР—Р”, С…С–СЂСѓСЂРіС–СЏ, РєР°СЃС‚СЂР°С†С–СЏ, РЅРµРІСЂРѕР»РѕРіС–СЏ.</p>`
        }
      </div>
    </div>
  `;
}

function renderStaffSkillCard(skill) {
  const icon = getSkillIcon(skill);

  return `
    <div class="staffSkillCard">
      <button class="staffSkillRemove" type="button" data-remove-skill="${escapeHtml(skill)}">Г—</button>
      <div class="staffSkillIcon">${icon}</div>
      <b>${escapeHtml(skill)}</b>
      <span>${escapeHtml(getSkillDescription(skill))}</span>
    </div>
  `;
}

function bindStaffSkillsPanel(root, state) {
  root.querySelector("#btnAddStaffSkill")?.addEventListener("click", () => {
    openStaffSkillModal(root, state);
  });

  root.querySelectorAll("[data-remove-skill]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const skill = btn.dataset.removeSkill;
      const skills = getStaffSkills(state.doc);
      const updatedSkills = skills.filter((s) => s !== skill);

      await updateStaffApi(state.doc.id, {
        ...state.doc,
        skills: updatedSkills,
      });

      state.doc.skills = updatedSkills;
      renderTeamOverviewTab(root, state);
    });
  });
}

function openStaffSkillModal(root, state) {
  const existing = document.querySelector(".staffSkillModalOverlay");
  existing?.remove();

  const presets = ["РЈР—Р”", "РҐС–СЂСѓСЂРіС–СЏ", "РљР°СЃС‚СЂР°С†С–СЏ", "РќРµРІСЂРѕР»РѕРіС–СЏ", "Р”РµСЂРјР°С‚РѕР»РѕРіС–СЏ", "РљР°СЂРґС–РѕР»РѕРіС–СЏ"];

  const modal = document.createElement("div");
  modal.className = "staffSkillModalOverlay";

  modal.innerHTML = `
    <div class="staffSkillModal">
      <button class="staffSkillModalClose" type="button">Г—</button>

      <div class="staffSkillModalHead">
        <div class="staffSkillModalIcon">рџ§ </div>
        <div>
          <h2>Р”РѕРґР°С‚Рё РЅР°РІРёС‡РєСѓ</h2>
          <p>Р’РєР°Р¶С–С‚СЊ РїСЂРѕС„РµСЃС–Р№РЅСѓ РЅР°РІРёС‡РєСѓ СЃРїС–РІСЂРѕР±С–С‚РЅРёРєР°.</p>
        </div>
      </div>

      <label class="staffSkillField">
        <span>РќР°Р·РІР° РЅР°РІРёС‡РєРё</span>
        <input id="staffSkillInput" type="text" placeholder="РќР°РїСЂРёРєР»Р°Рґ: РЈР—Р”, С…С–СЂСѓСЂРіС–СЏ, РєР°СЃС‚СЂР°С†С–СЏ">
      </label>

      <div class="staffSkillPresets">
        <span>РџРѕРїСѓР»СЏСЂРЅС– РЅР°РІРёС‡РєРё</span>
        <div>
          ${presets.map((p) => `
            <button type="button" data-skill-preset="${escapeHtml(p)}">
              ${getSkillIcon(p)} ${escapeHtml(p)}
            </button>
          `).join("")}
        </div>
      </div>

      <div class="staffSkillModalActions">
        <button class="teamGhostBtn" type="button" id="btnCancelSkill">РЎРєР°СЃСѓРІР°С‚Рё</button>
        <button class="teamPrimaryBtn" type="button" id="btnSaveSkill">Р”РѕРґР°С‚Рё +</button>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  const input = modal.querySelector("#staffSkillInput");
  input?.focus();

  const close = () => modal.remove();

  modal.querySelector(".staffSkillModalClose")?.addEventListener("click", close);
  modal.querySelector("#btnCancelSkill")?.addEventListener("click", close);

  modal.querySelectorAll("[data-skill-preset]").forEach((btn) => {
    btn.addEventListener("click", () => {
      input.value = btn.dataset.skillPreset || "";
      input.focus();
    });
  });

  modal.querySelector("#btnSaveSkill")?.addEventListener("click", async () => {
    const cleanSkill = input.value.trim();
    if (!cleanSkill) return;

    const skills = getStaffSkills(state.doc);

    if (skills.some((s) => s.toLowerCase() === cleanSkill.toLowerCase())) {
      alert("РўР°РєР° РЅР°РІРёС‡РєР° РІР¶Рµ С”.");
      return;
    }

    const updatedSkills = [...skills, cleanSkill];

    await updateStaffApi(state.doc.id, {
      ...state.doc,
      skills: updatedSkills,
    });

    state.doc.skills = updatedSkills;
    close();
    renderTeamOverviewTab(root, state);
  });
}
function getSkillIcon(skill) {
  const s = String(skill || "").toLowerCase();

  if (s.includes("СѓР·Рґ") || s.includes("СѓР»СЊС‚СЂР°")) return "рџ–ҐпёЏ";
  if (s.includes("С…С–СЂСѓСЂ") || s.includes("С…РёСЂСѓСЂРі")) return "вњ‚пёЏ";
  if (s.includes("РєР°СЃС‚СЂ") || s.includes("СЃС‚РµСЂРёР»")) return "рџђѕ";
  if (s.includes("РЅРµРІСЂРѕ")) return "рџ§ ";
  if (s.includes("РґРµСЂРјР°С‚")) return "рџ©№";
  if (s.includes("РєР°СЂРґС–") || s.includes("РєР°СЂРґРёРѕ")) return "вќ¤пёЏ";

  return "вњЁ";
}

function getSkillDescription(skill) {
  const s = String(skill || "").toLowerCase();

  if (s.includes("СѓР·Рґ")) return "Р”С–Р°РіРЅРѕСЃС‚РёРєР° Р·Р° РґРѕРїРѕРјРѕРіРѕСЋ СѓР»СЊС‚СЂР°Р·РІСѓРєСѓ";
  if (s.includes("С…С–СЂСѓСЂ") || s.includes("С…РёСЂСѓСЂРі")) return "РҐС–СЂСѓСЂРіС–С‡РЅС– РІС‚СЂСѓС‡Р°РЅРЅСЏ СЂС–Р·РЅРѕС— СЃРєР»Р°РґРЅРѕСЃС‚С–";
  if (s.includes("РєР°СЃС‚СЂ") || s.includes("СЃС‚РµСЂРёР»")) return "РЎС‚РµСЂРёР»С–Р·Р°С†С–СЏ С‚Р° РєР°СЃС‚СЂР°С†С–СЏ С‚РІР°СЂРёРЅ";
  if (s.includes("РЅРµРІСЂРѕ")) return "Р”С–Р°РіРЅРѕСЃС‚РёРєР° С‚Р° Р»С–РєСѓРІР°РЅРЅСЏ РЅРµСЂРІРѕРІРѕС— СЃРёСЃС‚РµРјРё";
  if (s.includes("РґРµСЂРјР°С‚")) return "РЁРєС–СЂР°, С€РµСЂСЃС‚СЊ, Р°Р»РµСЂРіС–С— С‚Р° РґРµСЂРјР°С‚РѕР»РѕРіС–СЏ";
  if (s.includes("РєР°СЂРґС–") || s.includes("РєР°СЂРґРёРѕ")) return "РЎРµСЂС†Рµ, СЃСѓРґРёРЅРё С‚Р° РєР°СЂРґС–РѕР»РѕРіС–С‡РЅР° РґС–Р°РіРЅРѕСЃС‚РёРєР°";

  return "РџСЂРѕС„РµСЃС–Р№РЅР° РЅР°РІРёС‡РєР° СЃРїС–РІСЂРѕР±С–С‚РЅРёРєР°";
}

