function renderClinicRatingBoard(rows, currentStaffId, seasonKey) {
  if (!rows.length) {
    return `
      <section class="clinicRatingBoard">
        <div class="clinicRatingHead">
          <div>
            <h3>рџЏ† Р РµР№С‚РёРЅРі РєР»С–РЅС–РєРё</h3>
            <p>РџРѕРєРё РЅРµРјР°С” РґР°РЅРёС… СЂРµР№С‚РёРЅРіСѓ. РџРµСЂРµСЂР°С…СѓР№С‚Рµ СЃРµР·РѕРЅ РЅР° СЃРµСЂРІРµСЂС–.</p>
          </div>
        </div>
      </section>
    `;
  }

  const seasonLabel = formatSeasonLabel(seasonKey);

  return `
    <section class="clinicRatingBoard">
      <div class="clinicRatingHead">
        <div>
          <h3>рџЏ† Р РµР№С‚РёРЅРі РєР»С–РЅС–РєРё</h3>
          <p>РЎРµР·РѕРЅ ${escapeHtml(seasonLabel)} В· РѕРЅРѕРІР»РµРЅРЅСЏ РєРѕР¶РЅС– 3 РјС–СЃСЏС†С–</p>
        </div>
        <span>${escapeHtml(seasonKey || "вЂ”")}</span>
      </div>

      <div class="clinicRatingTable">
        ${rows.map((r) => renderClinicRatingRow(r, currentStaffId)).join("")}
      </div>
    </section>
  `;
}

function renderClinicRatingRow(r, currentStaffId) {
  const rank = Number(r.rank || 0);
  const isCurrent = String(r.staff_id) === String(currentStaffId);

  const medal =
    rank === 1 ? "рџҐ‡" :
    rank === 2 ? "рџҐ€" :
    rank === 3 ? "рџҐ‰" :
    `#${rank}`;

  const avatar = r.avatar
    ? `<img src="${escapeHtml(r.avatar)}" alt="${escapeHtml(r.staff_name || "РџСЂР°С†С–РІРЅРёРє")}">`
    : `<span>${escapeHtml(String(r.staff_name || "?").trim().charAt(0).toUpperCase() || "?")}</span>`;

  return `
    <div class="clinicRatingRow ${isCurrent ? "current" : ""} rank-${rank}">
      <div class="clinicRatingPlace">${medal}</div>

      <div class="clinicRatingAvatar">
        ${avatar}
      </div>

      <div class="clinicRatingPerson">
        <b>${escapeHtml(r.staff_name || "РџСЂР°С†С–РІРЅРёРє")}</b>
        <span>${isCurrent ? "Р’Р°С€ РїСЂРѕС„С–Р»СЊ" : "РЎРїС–РІСЂРѕР±С–С‚РЅРёРє РєР»С–РЅС–РєРё"}</span>
      </div>

      <div class="clinicRatingStats">
        <div><span>Score</span><b>${Number(r.score || 0).toLocaleString("uk-UA")}</b></div>
        <div><span>Р’С–Р·РёС‚Рё</span><b>${Number(r.visits_count || 0).toLocaleString("uk-UA")}</b></div>
        <div><span>Р’РёСЂСѓС‡РєР°</span><b>${Number(r.revenue || 0).toLocaleString("uk-UA")} РіСЂРЅ</b></div>
        <div><span>РЎРµСЂ. С‡РµРє</span><b>${Number(r.avg_check || 0).toLocaleString("uk-UA")} РіСЂРЅ</b></div>
      </div>
    </div>
  `;
}

function formatSeasonLabel(seasonKey) {
  const s = String(seasonKey || "");
  const [year, q] = s.split("-Q");

  const map = {
    "1": "I РєРІР°СЂС‚Р°Р»",
    "2": "II РєРІР°СЂС‚Р°Р»",
    "3": "III РєРІР°СЂС‚Р°Р»",
    "4": "IV РєРІР°СЂС‚Р°Р»",
  };

  return `${map[q] || "РїРѕС‚РѕС‡РЅРёР№ СЃРµР·РѕРЅ"} ${year || ""}`.trim();
}

function buildStaffCareer(state) {
  const visits = state.dashboard.live_staff_visits || [];
  const revenue = Number(state.revenue || 0);

  const totalVisits = visits.length;
  const dogVisits = countVisitsBySpecies(visits, ["dog", "СЃРѕР±", "РїРµСЃ", "РїС‘СЃ"]);
  const catVisits = countVisitsBySpecies(visits, ["cat", "РєС–С‚", "РєРѕС‚", "РєРѕС€"]);
  const vaccineVisits = countVisitsByText(visits, ["РІР°РєС†РёРЅ", "С‰РµРїР»", "vaccine"]);
  const surgeryVisits = countVisitsByText(visits, ["РѕРїРµСЂР°С†", "С…С–СЂСѓСЂРі", "С…РёСЂСѓСЂРі", "surgery"]);

  const achievements = getVeterinaryAchievements({
    totalVisits,
    dogVisits,
    catVisits,
    revenue,
    vaccineVisits,
    surgeryVisits,
    consecutiveShifts: 0,
  });

  const unlocked = achievements.filter((a) => a.unlocked);
  const xp = achievements.reduce((sum, a) => {
    return sum + (a.unlocked ? Number(a.xp || 0) : 0);
  }, totalVisits * 10);

  const level = calculateCareerLevel(xp);
  const title = getCareerTitle(totalVisits);
  const levelIcon = getCareerIcon(totalVisits);

  return {
    xp,
    level: level.level,
    xpInLevel: level.xpInLevel,
    neededForNext: level.neededForNext,
    nextLevelXp: level.nextLevelXp,
    progressPercent: level.progressPercent,
    title,
    levelIcon,
    achievements,
    unlockedCount: unlocked.length,
    clinicRank: "вЂ”",
  };
}

async function loadStaffAccountApi(
  staffId
) {
  if (
    typeof isOwner === "function" &&
    !isOwner()
  ) {
    return {
      ok: false,
      skipped: true,
      error: "",
      data: null,
    };
  }

  try {
    const response =
      await fetch(
        `/api/staff/${
          encodeURIComponent(
            String(staffId)
          )
        }/account`,
        {
          method: "GET",
          credentials: "include",

          headers: {
            Accept:
              "application/json",
          },
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      json?.ok !== true
    ) {
      console.error(
        "loadStaffAccountApi:",
        response.status,
        json || text
      );

      return {
        ok: false,
        error:
          json?.error ||
          "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё Р°РєР°СѓРЅС‚",
        data: null,
      };
    }

    return {
      ok: true,
      data:
        json?.data || null,
    };

  } catch (error) {
    console.error(
      "loadStaffAccountApi failed:",
      error
    );

    return {
      ok: false,
      error:
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·'С”РґРЅР°С‚РёСЃСЏ С–Р· СЃРµСЂРІРµСЂРѕРј",
      data: null,
    };
  }
}


async function createStaffAccountApi(
  staffId,
  payload
) {
  if (
    typeof isOwner === "function" &&
    !isOwner()
  ) {
    return {
      ok: false,
      error:
        "РЎС‚РІРѕСЂСЋРІР°С‚Рё Р°РєР°СѓРЅС‚Рё СЃРїС–РІСЂРѕР±С–С‚РЅРёРєС–РІ РјРѕР¶Рµ Р»РёС€Рµ РІР»Р°СЃРЅРёРє РєР»С–РЅС–РєРё.",
      data: null,
    };
  }

  try {
    const response =
      await fetch(
        `/api/staff/${
          encodeURIComponent(
            String(staffId)
          )
        }/account`,
        {
          method: "POST",
          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",
          },

          body:
            JSON.stringify(
              payload || {}
            ),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      json?.ok !== true
    ) {
      return {
        ok: false,
        data: null,
        error:
          json?.error ||
          `HTTP ${response.status}`,
      };
    }

    return {
      ok: true,
      data:
        json?.data || null,
      error: "",
    };

  } catch (error) {
    console.error(
      "createStaffAccountApi failed:",
      error
    );

    return {
      ok: false,
      data: null,
      error:
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·'С”РґРЅР°С‚РёСЃСЏ С–Р· СЃРµСЂРІРµСЂРѕРј",
    };
  }
}

async function updateStaffAccountApi(
  staffId,
  payload
) {
  try {
    const response =
      await fetch(
        `/api/staff/${
          encodeURIComponent(
            String(staffId)
          )
        }/account`,
        {
          method: "PUT",
          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",
          },

          body: JSON.stringify(
            payload || {}
          ),
        }
      );

    const json =
      await response.json();

    return {
      ok:
        response.ok &&
        json?.ok === true,

      data:
        json?.data || null,

      error:
        json?.error || "",
    };
  } catch (error) {
    console.error(
      "updateStaffAccountApi failed:",
      error
    );

    return {
      ok: false,
      error:
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·'С”РґРЅР°С‚РёСЃСЏ С–Р· СЃРµСЂРІРµСЂРѕРј",
    };
  }
}


