function formatStaffLastLogin(
  value
) {
  if (!value) {
    return "Р©Рµ РЅРµ РІС…РѕРґРёРІ";
  }

  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return String(value);
  }

  return date.toLocaleString(
    "uk-UA",
    {
      dateStyle: "medium",
      timeStyle: "short",
    }
  );
}


