function bindStaffAccountPanel(
  root,
  profileState,
  accountResult
) {
  const staffId =
    profileState.doc?.id;

  if (!staffId) return;

  const account =
    accountResult?.data || null;

  root
    .querySelector(
      "#btnCreateStaffAccount"
    )
    ?.addEventListener(
      "click",
      async () => {
        const username =
          String(
            root.querySelector(
              "#staffAccountUsername"
            )?.value || ""
          ).trim();

        const role =
          String(
            root.querySelector(
              "#staffAccountRole"
            )?.value || "vet"
          );

        const password =
          String(
            root.querySelector(
              "#staffAccountPassword"
            )?.value || ""
          );

        if (username.length < 3) {
          openDeleteModal(
            "Р›РѕРіС–РЅ РїРѕРІРёРЅРµРЅ РјС–СЃС‚РёС‚Рё РјС–РЅС–РјСѓРј 3 СЃРёРјРІРѕР»Рё.",
            null,
            "info"
          );

          return;
        }

        if (password.length < 8) {
          openDeleteModal(
            "РўРёРјС‡Р°СЃРѕРІРёР№ РїР°СЂРѕР»СЊ РїРѕРІРёРЅРµРЅ РјС–СЃС‚РёС‚Рё РјС–РЅС–РјСѓРј 8 СЃРёРјРІРѕР»С–РІ.",
            null,
            "info"
          );

          return;
        }

        const result =
          await createStaffAccountApi(
            staffId,
            {
              username,
              role,
              password,
            }
          );

        if (!result.ok) {
          openDeleteModal(
            result.error ||
            "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё Р°РєР°СѓРЅС‚.",
            null,
            "info"
          );

          return;
        }

        await renderTeamSettingsTab(
          root,
          profileState
        );

        openDeleteModal(
          "РџРµСЂРµРґР°Р№С‚Рµ СЃРїС–РІСЂРѕР±С–С‚РЅРёРєСѓ Р»РѕРіС–РЅ С– С‚РёРјС‡Р°СЃРѕРІРёР№ РїР°СЂРѕР»СЊ.",
          null,
          "success"
        );
      }
    );

  root
    .querySelector(
      "#btnSaveStaffAccount"
    )
    ?.addEventListener(
      "click",
      async () => {
        const username =
          String(
            root.querySelector(
              "#staffAccountUsername"
            )?.value || ""
          ).trim();

        const role =
          String(
            root.querySelector(
              "#staffAccountRole"
            )?.value || "vet"
          );

        const result =
          await updateStaffAccountApi(
            staffId,
            {
              username,
              role,
            }
          );

        if (!result.ok) {
          openDeleteModal(
            result.error ||
            "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р±РµСЂРµРіС‚Рё Р·РјС–РЅРё.",
            null,
            "info"
          );

          return;
        }

        await renderTeamSettingsTab(
          root,
          profileState
        );

        openDeleteModal(
          "РќР°Р»Р°С€С‚СѓРІР°РЅРЅСЏ РґРѕСЃС‚СѓРїСѓ СѓСЃРїС–С€РЅРѕ Р·Р±РµСЂРµР¶РµРЅРѕ.",
          null,
          "success"
        );
      }
    );

  root
    .querySelector(
      "#btnToggleStaffAccount"
    )
    ?.addEventListener(
      "click",
      () => {
        if (!account) return;

        const nextActive =
          !account.is_active;

        openDeleteModal(
          nextActive
            ? "Р’С–РґРЅРѕРІРёС‚Рё С†СЊРѕРјСѓ СЃРїС–РІСЂРѕР±С–С‚РЅРёРєСѓ РґРѕСЃС‚СѓРї РґРѕ CRM?"
            : "РЎРїС–РІСЂРѕР±С–С‚РЅРёРє Р±С–Р»СЊС€Рµ РЅРµ Р·РјРѕР¶Рµ СѓРІС–Р№С‚Рё РґРѕ CRM.",
          async () => {
            const result =
              await updateStaffAccountApi(
                staffId,
                {
                  is_active:
                    nextActive,
                }
              );

            if (!result.ok) {
              openDeleteModal(
                result.error ||
                "РќРµ РІРґР°Р»РѕСЃСЏ Р·РјС–РЅРёС‚Рё РґРѕСЃС‚СѓРї.",
                null,
                "info"
              );

              return;
            }

            await renderTeamSettingsTab(
              root,
              profileState
            );

            openDeleteModal(
              nextActive
                ? "Р”РѕСЃС‚СѓРї РґРѕ CRM СѓРІС–РјРєРЅРµРЅРѕ."
                : "Р”РѕСЃС‚СѓРї РґРѕ CRM РІРёРјРєРЅРµРЅРѕ.",
              null,
              "success"
            );
          },
          nextActive
            ? "activate"
            : "deactivate"
        );
      }
    );

  root
  .querySelector(
    "#btnResetStaffPassword"
  )
  ?.addEventListener(
    "click",
    async () => {
      const password =
        prompt(
          "Р’РІРµРґС–С‚СЊ РЅРѕРІРёР№ С‚РёРјС‡Р°СЃРѕРІРёР№ РїР°СЂРѕР»СЊ. РњС–РЅС–РјСѓРј 8 СЃРёРјРІРѕР»С–РІ:"
        );

      if (password === null) {
        return;
      }

      const cleanPassword =
        String(password).trim();

      if (
        cleanPassword.length < 8
      ) {
        openDeleteModal(
          "РџР°СЂРѕР»СЊ РїРѕРІРёРЅРµРЅ РјС–СЃС‚РёС‚Рё РјС–РЅС–РјСѓРј 8 СЃРёРјРІРѕР»С–РІ.",
          null,
          "info"
        );

        return;
      }

      const result =
        await resetStaffPasswordApi(
          staffId,
          cleanPassword
        );

      if (!result.ok) {
        openDeleteModal(
          result.error ||
          "РќРµ РІРґР°Р»РѕСЃСЏ СЃРєРёРЅСѓС‚Рё РїР°СЂРѕР»СЊ.",
          null,
          "info"
        );

        return;
      }

      await renderTeamSettingsTab(
        root,
        profileState
      );

      openDeleteModal(
        "РўРёРјС‡Р°СЃРѕРІРёР№ РїР°СЂРѕР»СЊ РІСЃС‚Р°РЅРѕРІР»РµРЅРѕ. РџСЂРё РЅР°СЃС‚СѓРїРЅРѕРјСѓ РІС…РѕРґС– СЃРїС–РІСЂРѕР±С–С‚РЅРёРє РїРѕРІРёРЅРµРЅ СЃС‚РІРѕСЂРёС‚Рё РЅРѕРІРёР№ РїР°СЂРѕР»СЊ.",
        null,
        "success"
      );
    }
  );
}
