function getStockCategories(
  items
) {
  const usedCategories =
    new Set(
      (items || [])
        .map((item) =>
          String(
            item?.category ||
            item?.cat ||
            "Р†РЅС€Рµ"
          ).trim()
        )
        .filter(Boolean)
    );

  const ordered = [];

  STOCK_CATEGORY_GROUPS.forEach(
    (group) => {
      group.categories.forEach(
        (category) => {
          if (
            usedCategories.has(
              category
            )
          ) {
            ordered.push(category);
          }
        }
      );
    }
  );

  usedCategories.forEach(
    (category) => {
      if (
        !ordered.includes(category)
      ) {
        ordered.push(category);
      }
    }
  );

  return ordered;
}


function getStockStatus(item) {
  const quantity = Math.max(
    0,
    Number(item?.qty || 0)
  );

  const minimum = Math.max(
    0,
    Number(
      item?.min_qty ??
      item?.minimum_qty ??
      5
    )
  );

  if (quantity <= 0) {
    return {
      key: "empty",
      label: "РќРµРјР°С” РІ РЅР°СЏРІРЅРѕСЃС‚С–",
      shortLabel: "РќРµРјР°С”",
      icon: "в—‹",
    };
  }

  if (quantity <= minimum) {
    return {
      key: "critical",
      label: "РљСЂРёС‚РёС‡РЅРёР№ Р·Р°Р»РёС€РѕРє",
      shortLabel: "РљСЂРёС‚РёС‡РЅРѕ",
      icon: "!",
    };
  }

  if (quantity <= minimum * 2) {
    return {
      key: "low",
      label: "Р—Р°РєС–РЅС‡СѓС”С‚СЊСЃСЏ",
      shortLabel: "РњР°Р»Рѕ",
      icon: "в†“",
    };
  }

  return {
    key: "good",
    label: "Р”РѕСЃС‚Р°С‚РЅС–Р№ Р·Р°РїР°СЃ",
    shortLabel: "Р’ РЅР°СЏРІРЅРѕСЃС‚С–",
    icon: "вњ“",
  };
}


function parseStockDate(value) {
  const match =
    String(value || "")
      .match(
        /^(\d{4})-(\d{2})-(\d{2})$/
      );

  if (!match) return null;

  const parsed =
    new Date(
      Number(match[1]),
      Number(match[2]) - 1,
      Number(match[3])
    );

  return Number.isNaN(
    parsed.getTime()
  )
    ? null
    : parsed;
}


function formatStockDate(value) {
  const parsed =
    parseStockDate(value);

  return parsed
    ? parsed.toLocaleDateString(
        "uk-UA"
      )
    : "";
}


function getStockExpiryMeta(
  item,
  now = new Date()
) {
  const expiryDate =
    parseStockDate(
      item?.expiry_date
    );

  if (!expiryDate) {
    return {
      key: "none",
      days: null,
      label: "",
    };
  }

  const today =
    new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate()
    );

  const days =
    Math.ceil(
      (
        expiryDate.getTime()
        - today.getTime()
      )
      / 86400000
    );

  if (days < 0) {
    return {
      key: "expired",
      days,
      label: "РўРµСЂРјС–РЅ РјРёРЅСѓРІ",
    };
  }

  if (days <= 30) {
    return {
      key: "critical",
      days,
      label:
        days === 0
          ? "РћСЃС‚Р°РЅРЅС–Р№ РґРµРЅСЊ"
          : `${days} РґРЅ. РґРѕ Р·Р°РІРµСЂС€РµРЅРЅСЏ`,
    };
  }

  if (days <= 90) {
    return {
      key: "warning",
      days,
      label:
        `${days} РґРЅ. РґРѕ Р·Р°РІРµСЂС€РµРЅРЅСЏ`,
    };
  }

  return {
    key: "good",
    days,
    label:
      `РџСЂРёРґР°С‚РЅРёР№ РґРѕ ${formatStockDate(
        item.expiry_date
      )}`,
  };
}


function buildStockPugInsights(items) {
  const signals = [];
  const attentionItemIds =
    new Set();
  let expiryRiskCount = 0;
  let forecastRiskCount = 0;
  let valueAtRisk = 0;

  (items || [])
    .filter(
      (item) =>
        item?.active !== false
    )
    .forEach((item) => {
      const itemId =
        String(item.id || "");
      const quantity =
        Math.max(
          0,
          Number(item.qty || 0)
        );
      const minimum =
        Math.max(
          0,
          Number(item.min_qty || 0)
        );
      const cost =
        Math.max(
          0,
          Number(item.cost || 0)
        );
      const expiry =
        getStockExpiryMeta(item);
      const estimatedDaysLeft =
        item.estimated_days_left ==
        null
          ? null
          : Math.max(
              0,
              Number(
                item.estimated_days_left
              )
            );

      if (
        expiry.key === "expired" ||
        expiry.key === "critical"
      ) {
        expiryRiskCount += 1;
        attentionItemIds.add(itemId);
        valueAtRisk +=
          quantity * cost;

        signals.push({
          priority:
            expiry.key === "expired"
              ? 0
              : 1,
          tone:
            expiry.key === "expired"
              ? "danger"
              : "warning",
          icon:
            expiry.key === "expired"
              ? "!"
              : "в—·",
          itemId,
          title:
            expiry.key === "expired"
              ? `${item.name}: С‚РµСЂРјС–РЅ РїСЂРёРґР°С‚РЅРѕСЃС‚С– РјРёРЅСѓРІ`
              : `${item.name}: ${expiry.label.toLowerCase()}`,
          description:
            quantity > 0
              ? `РџС–Рґ СЂРёР·РёРєРѕРј ${quantity.toLocaleString(
                  "uk-UA"
                )} ${item.unit}.`
              : "РџРµСЂРµРІС–СЂС‚Рµ РїРѕР·РёС†С–СЋ РїРµСЂРµРґ РІРёРєРѕСЂРёСЃС‚Р°РЅРЅСЏРј.",
        });
      }

      if (quantity <= 0) {
        attentionItemIds.add(itemId);

        signals.push({
          priority: 0,
          tone: "danger",
          icon: "0",
          itemId,
          title:
            `${item.name} Р·Р°РєС–РЅС‡РёРІСЃСЏ`,
          description:
            minimum > 0
              ? `Р РµРєРѕРјРµРЅРґРѕРІР°РЅРёР№ РјС–РЅС–РјСѓРј вЂ” ${minimum.toLocaleString(
                  "uk-UA"
                )} ${item.unit}.`
              : "РџРѕР·РёС†С–СЏ РЅРµРґРѕСЃС‚СѓРїРЅР° РґР»СЏ РІРёРєРѕСЂРёСЃС‚Р°РЅРЅСЏ.",
        });
      } else if (
        quantity <= minimum
      ) {
        attentionItemIds.add(itemId);

        signals.push({
          priority: 1,
          tone: "warning",
          icon: "в†“",
          itemId,
          title:
            `${item.name}: РєСЂРёС‚РёС‡РЅРёР№ Р·Р°Р»РёС€РѕРє`,
          description:
            `Р—Р°Р»РёС€РёР»РѕСЃСЊ ${quantity.toLocaleString(
              "uk-UA"
            )} ${item.unit}, РјС–РЅС–РјСѓРј вЂ” ${minimum.toLocaleString(
              "uk-UA"
            )}.`,
        });
      }

      if (
        estimatedDaysLeft != null &&
        estimatedDaysLeft > 0 &&
        estimatedDaysLeft <= 14 &&
        quantity > minimum
      ) {
        forecastRiskCount += 1;
        attentionItemIds.add(itemId);

        signals.push({
          priority:
            estimatedDaysLeft <= 7
              ? 1
              : 2,
          tone:
            estimatedDaysLeft <= 7
              ? "warning"
              : "info",
          icon: "в†",
          itemId,
          title:
            `${item.name} РІРёСЃС‚Р°С‡РёС‚СЊ РїСЂРёР±Р»РёР·РЅРѕ РЅР° ${Math.max(
              1,
              Math.round(
                estimatedDaysLeft
              )
            )} РґРЅ.`,
          description:
            "РџСЂРѕРіРЅРѕР· Р·Р° СЃРїРёСЃР°РЅРЅСЏРјРё РѕСЃС‚Р°РЅРЅС–С… 30 РґРЅС–РІ.",
        });
      }
    });

  signals.sort(
    (left, right) =>
      left.priority -
      right.priority
  );

  return {
    signals,
    attentionCount:
      attentionItemIds.size,
    expiryRiskCount,
    forecastRiskCount,
    valueAtRisk,
  };
}


function normalizeStockItem(item) {
  const category =
    String(
      item?.category ||
      item?.cat ||
      "Р†РЅС€Рµ"
    );

  const group =
    getStockGroupByCategory(
      category
    );

  return {
    ...item,

    id:
      String(
        item?.id ||
        `stk_${Date.now()
          .toString(36)}`
      ),

    name:
      String(
        item?.name ||
        "РџРѕР·РёС†С–СЏ"
      ),

    group:
      String(
        item?.group ||
        item?.group_id ||
        group?.id ||
        "other"
      ),

    category,

    form:
      String(
        item?.form ||
        item?.dosage_form ||
        "Р†РЅС€Рµ"
      ),

    route:
      String(
        item?.route ||
        item?.administration_route ||
        "РќРµ Р·Р°СЃС‚РѕСЃРѕРІСѓС”С‚СЊСЃСЏ"
      ),

    species:
      String(
        item?.species ||
        item?.target_species ||
        "РЈРЅС–РІРµСЂСЃР°Р»СЊРЅРёР№"
      ),

    unit:
      String(
        item?.unit ||
        "С€С‚"
      ),

    qty:
      Math.max(
        0,
        Number(item?.qty || 0)
      ),

    price:
      Math.max(
        0,
        Number(
          item?.price ??
          item?.sell_price ??
          0
        )
      ),

    cost:
      Math.max(
        0,
        Number(
          item?.cost ??
          item?.purchase_price ??
          0
        )
      ),

    min_qty:
      Math.max(
        0,
        Number(
          item?.min_qty ??
          item?.minimum_qty ??
          5
        )
      ),

    expiry_date:
      String(
        item?.expiry_date || ""
      ).trim() || null,

    batch_number:
      String(
        item?.batch_number || ""
      ).trim() || null,

    usage_30d:
      Math.max(
        0,
        Number(
          item?.usage_30d || 0
        )
      ),

    avg_daily_usage:
      Math.max(
        0,
        Number(
          item?.avg_daily_usage || 0
        )
      ),

    estimated_days_left:
      item?.estimated_days_left ==
      null
        ? null
        : Math.max(
            0,
            Number(
              item.estimated_days_left
            )
          ),

    active:
      item?.active !== false,
  };
}


function saveNormalizedStock(items) {
  const normalized =
    (items || []).map(
      normalizeStockItem
    );

  saveStock(normalized);

  return normalized;
}

