function financeDateToIso(
  date
) {
  const year =
    date.getFullYear();

  const month =
    String(
      date.getMonth() + 1
    ).padStart(2, "0");

  const day =
    String(
      date.getDate()
    ).padStart(2, "0");

  return (
    `${year}-${month}-${day}`
  );
}

function getFinancePresetDates(
  preset = "month"
) {
  const today =
    new Date();

  const dateTo =
    new Date(
      today.getFullYear(),
      today.getMonth(),
      today.getDate()
    );

  let dateFrom =
    new Date(dateTo);

  if (
    preset === "week"
  ) {
    dateFrom.setDate(
      dateFrom.getDate() - 6
    );
  } else if (
    preset === "month"
  ) {
    dateFrom =
      new Date(
        dateTo.getFullYear(),
        dateTo.getMonth(),
        1
      );
  }

  return {
    dateFrom:
      financeDateToIso(
        dateFrom
      ),

    dateTo:
      financeDateToIso(
        dateTo
      ),
  };
}

