function buildFinanceSectionNavigation() {
  const sections = [
    {
      key: "today",
      icon: "вЊЃ",
      label: "РЎСЊРѕРіРѕРґРЅС–",
    },

    {
      key: "transactions",
      icon: "в†•",
      label: "РћРїРµСЂР°С†С–С—",
    },

    {
      key: "clients",
      icon: "в—Ћ",
      label: "РљР»С–С”РЅС‚Рё",
    },

    {
      key: "analytics",
      icon: "вЊЃ",
      label: "РђРЅР°Р»С–С‚РёРєР°",
    },

    ...(isOwner()
      ? [{
          key: "report",
          icon: "вњ¦",
          label: "Р—РІС–С‚ РІР»Р°СЃРЅРёРєР°",
        }]
      : []),
  ];

  return `
    <nav class="financeSectionNavigation">
      ${
        sections
          .map(
            (section) => `
              <button
                type="button"
                class="
                  financeSectionButton
                  ${
                    financeDashboardState
                      .section ===
                    section.key
                      ? "active"
                      : ""
                  }
                "
                data-finance-section="${
                  section.key
                }"
              >
                <span>
                  ${section.icon}
                </span>

                <strong>
                  ${section.label}
                </strong>
              </button>
            `
          )
          .join("")
      }
    </nav>
  `;
}

function bindFinanceSectionNavigation(
  page
) {
  page
    .querySelectorAll(
      "[data-finance-section]:not(:disabled)"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          () => {
            const section =
              button.dataset
                .financeSection ||
              "today";

            if (
              section ===
              financeDashboardState
                .section
            ) {
              return;
            }

            financeDashboardState.section =
              section;

            financeDashboardState
              .transactionOffset = 0;

            renderFinanceTab();
          }
        );
      }
    );
}

