function buildFinanceExpensesTrendChart(
  rows
) {
  const data =
    Array.isArray(rows)
      ? rows
      : [];

  const hasExpenses =
    data.some(
      (row) =>
        Number(
          row.amount || 0
        ) > 0
    );

  if (
    !data.length ||
    !hasExpenses
  ) {
    return `
      <div class="financeChartEmpty">
        <span>в€’</span>

        <strong>
          Р—Р° С†РµР№ РїРµСЂС–РѕРґ РІРёС‚СЂР°С‚ РЅРµРјР°С”
        </strong>

        <p>
          Р“СЂР°С„С–Рє Р·КјСЏРІРёС‚СЊСЃСЏ РїС–СЃР»СЏ
          РїСЂРѕРІРµРґРµРЅРЅСЏ РїРµСЂС€РѕС— РІРёС‚СЂР°С‚Рё.
        </p>
      </div>
    `;
  }

  const width = 860;
  const height = 260;

  const padLeft = 58;
  const padRight = 20;
  const padTop = 24;
  const padBottom = 42;

  const chartWidth =
    width -
    padLeft -
    padRight;

  const chartHeight =
    height -
    padTop -
    padBottom;

  const amounts =
    data.map(
      (row) =>
        Math.max(
          0,
          Number(
            row.amount || 0
          )
        )
    );

  const maxAmount =
    Math.max(
      ...amounts,
      1
    );

  const step =
    chartWidth /
    Math.max(
      data.length,
      1
    );

  const barWidth =
    Math.max(
      3,
      Math.min(
        24,
        step * 0.58
      )
    );

  const gridLines =
    [0, 0.25, 0.5, 0.75, 1]
      .map(
        (ratio) => {
          const y =
            padTop +
            chartHeight -
            chartHeight *
            ratio;

          const value =
            maxAmount *
            ratio;

          return `
            <line
              x1="${padLeft}"
              y1="${y}"
              x2="${width - padRight}"
              y2="${y}"
              class="financeExpenseGridLine"
            ></line>

            <text
              x="${padLeft - 10}"
              y="${y + 4}"
              text-anchor="end"
              class="financeExpenseGridLabel"
            >
              ${Math.round(value)
                .toLocaleString(
                  "uk-UA"
                )}
            </text>
          `;
        }
      )
      .join("");

  const labelStep =
    Math.max(
      1,
      Math.ceil(
        data.length / 7
      )
    );

  const bars =
    data.map(
      (
        row,
        index
      ) => {
        const amount =
          amounts[index];

        const barHeight =
          amount > 0
            ? Math.max(
                3,
                (
                  amount /
                  maxAmount
                ) *
                chartHeight
              )
            : 0;

        const x =
          padLeft +
          index * step +
          (
            step -
            barWidth
          ) /
          2;

        const y =
          padTop +
          chartHeight -
          barHeight;

        const shouldShowLabel =
          index === 0 ||
          index ===
            data.length - 1 ||
          index %
            labelStep ===
            0;

        const date =
          new Date(
            `${row.date}T00:00:00`
          );

        const dateLabel =
          Number.isNaN(
            date.getTime()
          )
            ? String(
                row.date || ""
              )
            : date
                .toLocaleDateString(
                  "uk-UA",
                  {
                    day:
                      "2-digit",

                    month:
                      "2-digit",
                  }
                );

        return `
          <g class="financeExpenseBarGroup">
            ${
              amount > 0
                ? `
                  <rect
                    x="${x}"
                    y="${y}"
                    width="${barWidth}"
                    height="${barHeight}"
                    rx="${Math.min(
                      6,
                      barWidth / 2
                    )}"
                    class="financeExpenseBar"
                  >
                    <title>
                      ${escapeHtml(
                        dateLabel
                      )}: ${escapeHtml(
                        formatVisitFinanceMoney(
                          amount
                        )
                      )}
                    </title>
                  </rect>

                  <circle
                    cx="${
                      x +
                      barWidth / 2
                    }"
                    cy="${y}"
                    r="3"
                    class="financeExpenseBarPoint"
                  ></circle>
                `
                : ""
            }

            ${
              shouldShowLabel
                ? `
                  <text
                    x="${
                      x +
                      barWidth / 2
                    }"
                    y="${
                      height - 14
                    }"
                    text-anchor="middle"
                    class="financeExpenseDateLabel"
                  >
                    ${escapeHtml(
                      dateLabel
                    )}
                  </text>
                `
                : ""
            }
          </g>
        `;
      }
    )
      .join("");

  return `
    <div class="financeExpenseTrendChart">
      <svg
        viewBox="0 0 ${width} ${height}"
        role="img"
        aria-label="Р”РёРЅР°РјС–РєР° РІРёС‚СЂР°С‚"
      >
        ${gridLines}
        ${bars}
      </svg>
    </div>
  `;
}
