function formatFinancePurchaseDate(
  value
) {
  if (!value) return "вЂ”";

  const date = new Date(
    `${value}T12:00:00`
  );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return value;
  }

  return date.toLocaleDateString(
    "uk-UA"
  );
}
