function openStockAdjustmentModal(
  stockItem,
  mode = "income"
) {
  document
    .getElementById(
      "stockAdjustmentModal"
    )
    ?.remove();

  const item =
    normalizeStockItem(
      stockItem
    );

  const isIncome =
    mode === "income";

  const modal =
    document.createElement("div");

  modal.id =
    "stockAdjustmentModal";

  modal.className =
    "stockAdjustmentOverlay";

  modal.innerHTML = `
    <div
      class="stockAdjustmentBackdrop"
      data-close-stock-adjustment
    ></div>

    <section class="stockAdjustmentModal">
      <button
        type="button"
        class="stockAdjustmentClose"
        data-close-stock-adjustment
      >
        вњ•
      </button>

      <div
        class="
          stockAdjustmentIcon
          ${isIncome ? "income" : "writeoff"}
        "
      >
        ${
          isIncome
            ? "пј‹"
            : "в€’"
        }
      </div>

      <div class="stockAdjustmentEyebrow">
        ${
          isIncome
            ? "РќРђР”РҐРћР”Р–Р•РќРќРЇ"
            : "РЎРџРРЎРђРќРќРЇ"
        }
      </div>

      <h2>
        ${
          isIncome
            ? "РџРѕРїРѕРІРЅРёС‚Рё Р·Р°Р»РёС€РѕРє"
            : "РЎРїРёСЃР°С‚Рё Р·С– СЃРєР»Р°РґСѓ"
        }
      </h2>

      <div class="stockAdjustmentItem">
        <span>
          ${getStockCategoryIcon(
            item.category
          )}
        </span>

        <div>
          <strong>
            ${escapeHtml(item.name)}
          </strong>

          <small>
            Р—Р°СЂР°Р·:
            ${item.qty}
            ${escapeHtml(item.unit)}
          </small>
        </div>
      </div>

      <label class="stockAdjustmentField">
        <span>
          РљС–Р»СЊРєС–СЃС‚СЊ,
          ${escapeHtml(item.unit)}
        </span>

        <input
          id="stockAdjustmentQuantity"
          type="number"
          min="0.01"
          step="0.01"
          placeholder="0"
        >
      </label>

      <label class="stockAdjustmentField">
        <span>
          РљРѕРјРµРЅС‚Р°СЂ
        </span>

        <textarea
          id="stockAdjustmentComment"
          rows="3"
          placeholder="${
            isIncome
              ? "РќР°РїСЂРёРєР»Р°Рґ, РЅРѕРІР° РїРѕСЃС‚Р°РІРєР°"
              : "РќР°РїСЂРёРєР»Р°Рґ, РІРёРєРѕСЂРёСЃС‚Р°РЅРѕ Р°Р±Рѕ РїСЂРѕСЃС‚СЂРѕС‡РµРЅРѕ"
          }"
        ></textarea>
      </label>

      <div class="stockAdjustmentResult">
        <span>
          РќРѕРІРёР№ Р·Р°Р»РёС€РѕРє
        </span>

        <strong id="stockAdjustmentResult">
          ${item.qty}
          ${escapeHtml(item.unit)}
        </strong>
      </div>

      <div class="stockAdjustmentActions">
        <button
          type="button"
          class="stockAdjustmentCancel"
          data-close-stock-adjustment
        >
          РЎРєР°СЃСѓРІР°С‚Рё
        </button>

        <button
          type="button"
          class="
            stockAdjustmentSubmit
            ${isIncome ? "income" : "writeoff"}
          "
          id="stockAdjustmentSubmit"
        >
          ${
            isIncome
              ? "РџРѕРїРѕРІРЅРёС‚Рё"
              : "РЎРїРёСЃР°С‚Рё"
          }
        </button>
      </div>
    </section>
  `;

  document.body.appendChild(modal);

  const quantityInput =
    modal.querySelector(
      "#stockAdjustmentQuantity"
    );

  const resultElement =
    modal.querySelector(
      "#stockAdjustmentResult"
    );

  const closeModal = () =>
    modal.remove();

  modal.addEventListener(
    "click",
    (event) => {
      if (
        event.target.closest(
          "[data-close-stock-adjustment]"
        )
      ) {
        closeModal();
      }
    }
  );

  const calculateResult = () => {
    const quantity =
      Math.max(
        0,
        Number(
          quantityInput?.value || 0
        )
      );

    const result =
      isIncome
        ? item.qty + quantity
        : Math.max(
            0,
            item.qty - quantity
          );

    if (resultElement) {
      resultElement.textContent =
        `${result} ${item.unit}`;
    }
  };

  quantityInput?.addEventListener(
    "input",
    calculateResult
  );

  const submitButton =
  modal.querySelector(
    "#stockAdjustmentSubmit"
  );

submitButton?.addEventListener(
  "click",
  async () => {
    const quantity =
      Math.max(
        0,
        Number(
          quantityInput?.value || 0
        )
      );

    if (!quantity) {
      alert(
        "Р’РєР°Р¶С–С‚СЊ РєС–Р»СЊРєС–СЃС‚СЊ."
      );

      quantityInput?.focus();
      return;
    }

    if (
      !isIncome &&
      quantity > item.qty
    ) {
      alert(
        `РќР° СЃРєР»Р°РґС– Р»РёС€Рµ ${item.qty} ${item.unit}.`
      );

      return;
    }

    const comment =
      modal
        .querySelector(
          "#stockAdjustmentComment"
        )
        ?.value
        ?.trim() || "";

    const originalButtonText =
      submitButton.textContent;

    submitButton.disabled = true;
    submitButton.textContent =
      "Р—Р±РµСЂРµР¶РµРЅРЅСЏвЂ¦";

    try {
      await adjustStockItemApi(
        item.id,
        {
          mode:
            isIncome
              ? "income"
              : "writeoff",

          quantity,
          comment,
        }
      );

      closeModal();
      renderStockTab();

    } catch (error) {
      console.error(
        "Stock adjustment failed:",
        error
      );

      alert(
        error?.message ||
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·РјС–РЅРёС‚Рё Р·Р°Р»РёС€РѕРє."
      );

    } finally {
      if (
        document.body.contains(
          submitButton
        )
      ) {
        submitButton.disabled =
          false;

        submitButton.textContent =
          originalButtonText;
      }
    }
  }
);

  setTimeout(() => {
    quantityInput?.focus();
  }, 50);
}


