async function deleteHospitalTaskApi(
  taskId
) {
  try {
    const response = await fetch(
      `/api/hospital-tasks/${encodeURIComponent(
        String(taskId)
      )}`,
      {
        method: "DELETE",
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...getOrgHeaders(),
        },
      }
    );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch (error) {
      console.error(
        "deleteHospitalTaskApi JSON error:",
        text
      );

      return false;
    }

    if (
      !response.ok ||
      json?.ok !== true
    ) {
      console.error(
        "deleteHospitalTaskApi failed:",
        response.status,
        json
      );

      return false;
    }

    return true;
  } catch (error) {
    console.error(
      "deleteHospitalTaskApi error:",
      error
    );

    return false;
  }
}
