    const results =
      await Promise.all([
        loadPatientsApi(),
        loadOwners(),
        loadStaffApi(),
      ]);

    patients =
      Array.isArray(results[0])
        ? results[0]
        : Array.isArray(state.patients)
          ? state.patients
          : [];

    owners =
      Array.isArray(results[1])
        ? results[1]
        : Array.isArray(state.owners)
          ? state.owners
          : [];

    staff =
      Array.isArray(results[2])
        ? results[2]
        : [];
