async function requestPatientAiSummary(patientId) {
  const controller =
    new AbortController();
  const timeoutId = setTimeout(
    () => controller.abort(),
    70000
  );

  try {
    const response = await fetch(
      `/api/patients/${encodeURIComponent(String(patientId))}/ai-summary`,
      {
        method: "POST",
        credentials: "include",
        signal: controller.signal,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          ...getOrgHeaders(),
        },
        body: JSON.stringify({
          language: "uk",
        }),
      }
    );

    const result = await response
      .json()
      .catch(() => null);

    if (!response.ok || !result?.ok) {
      throw new Error(
        result?.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё AI-РїС–РґСЃСѓРјРѕРє."
      );
    }

    return result.data;
  } finally {
    clearTimeout(timeoutId);
  }
}


function refreshPatientAiPanel(pet) {
  const panel = document.querySelector(
    `[data-pug-ai-panel="${CSS.escape(String(pet?.id || ""))}"]`
  );

  if (!panel) {
    return;
  }

  const replacement =
    document.createElement("div");

  replacement.innerHTML =
    renderPatientAiSummaryPanel(pet).trim();

  const nextPanel =
    replacement.firstElementChild;

  if (!nextPanel) {
    return;
  }

  panel.replaceWith(nextPanel);
  bindPatientAiSummaryPanel(pet);
}


function bindPatientAiSummaryPanel(pet) {
  const panel = document.querySelector(
    `[data-pug-ai-panel="${CSS.escape(String(pet?.id || ""))}"]`
  );

  if (!panel) {
    return;
  }

  panel
    .querySelector("[data-generate-pug-ai-summary]")
    ?.addEventListener("click", async () => {
      const patientId = String(pet.id);

      patientAiSummaryUiState.set(
        patientId,
        { status: "loading" }
      );

      refreshPatientAiPanel(pet);

      try {
        const data =
          await requestPatientAiSummary(patientId);

        patientAiSummaryUiState.set(
          patientId,
          {
            status: "ready",
            data,
          }
        );

      } catch (error) {
        console.error(
          "PUG AI SUMMARY UI:",
          error
        );

        patientAiSummaryUiState.set(
          patientId,
          {
            status: "error",
            error:
              error?.name === "AbortError"
                ? "РЎРµСЂРІРµСЂ РІС–РґРїРѕРІС–РґР°С” РЅР°РґС‚Рѕ РґРѕРІРіРѕ. РЎРїСЂРѕР±СѓР№С‚Рµ С‰Рµ СЂР°Р·."
                : error?.message ||
                  "РЎРїСЂРѕР±СѓР№С‚Рµ С‰Рµ СЂР°Р·.",
          }
        );
      }

      refreshPatientAiPanel(pet);
    });

  panel
    .querySelectorAll("[data-pug-ai-source]")
    .forEach((button) => {
      button.addEventListener("click", async () => {
        const sourceType =
          button.dataset.sourceType || "";
        const sourceId =
          button.dataset.sourceId || "";
        const recordedAt =
          button.dataset.recordedAt || "";

        if (sourceType === "visit" && sourceId) {
          await openVisit(sourceId);
          return;
        }

        showCrmNotice({
          icon: "рџ”—",
          title: "Р”Р¶РµСЂРµР»Рѕ AI-РІРёСЃРЅРѕРІРєСѓ",
          text: [
            patientAiSourceLabel({
              source_type: sourceType,
              recorded_at: recordedAt,
            }),
            sourceId ? `ID: ${sourceId}` : "",
          ].filter(Boolean).join(" В· "),
        });
      });
    });
}


