function findPatientDiagnosisById(
  diagnoses,
  diagnosisId
) {
  return (
    Array.isArray(diagnoses)
      ? diagnoses
      : []
  ).find(
    (item) =>
      String(item?.id) ===
      String(diagnosisId)
  ) || null;
}

function closePatientDiagnosisModal() {
  document
    .querySelector(
      ".patientDiagnosisModalOverlay"
    )
    ?.remove();
}

function createPatientDiagnosisModalShell(
  content
) {
  closePatientDiagnosisModal();

  const overlay =
    document.createElement("div");
  overlay.className =
    "patientDiagnosisModalOverlay";
  overlay.innerHTML = `
    <div
      class="patientDiagnosisModal"
      role="dialog"
      aria-modal="true"
    >
      ${content}
    </div>
  `;

  document.body.appendChild(overlay);

  overlay.addEventListener(
    "click",
    (event) => {
      if (
        event.target === overlay ||
        event.target.closest(
          "[data-close-diagnosis-modal]"
        )
      ) {
        closePatientDiagnosisModal();
      }
    }
  );

  const firstField =
    overlay.querySelector(
      "input, select, textarea, button"
    );
  firstField?.focus();

  return overlay;
}

function openPatientDiagnosisEditor(
  pet,
  diagnosis = null
) {
  const editing = Boolean(diagnosis);
  const dateValue = String(
    diagnosis?.diagnosed_at || ""
  ).slice(0, 10);
  const today = new Date()
    .toISOString()
    .slice(0, 10);
  const overlay =
    createPatientDiagnosisModalShell(`
      <header class="patientDiagnosisModalHeader">
  <div>
    <h3>
      ${
        editing
          ? "Р РµРґР°РіСѓРІР°С‚Рё РґС–Р°РіРЅРѕР·"
          : "Р”РѕРґР°С‚Рё РґС–Р°РіРЅРѕР·"
      }
    </h3>
          <p>
            ${escapeHtml(
              pet?.name || "РџР°С†С–С”РЅС‚"
            )}
          </p>
        </div>
        <button
          type="button"
          data-close-diagnosis-modal
          aria-label="Р—Р°РєСЂРёС‚Рё"
        >
          Г—
        </button>
      </header>

      <form class="patientDiagnosisForm">
        <label class="is-wide">
          <span>Р”С–Р°РіРЅРѕР· *</span>
          <input
            name="diagnosis_name"
            required
            maxlength="300"
            autocomplete="off"
            value="${escapeHtml(
              diagnosis?.diagnosis_name || ""
            )}"
            placeholder="РќР°РїСЂРёРєР»Р°Рґ: Р°С‚РѕРїС–С‡РЅРёР№ РґРµСЂРјР°С‚РёС‚"
          >
        </label>

        <label>
          <span>РљРѕРґ</span>
          <input
            name="diagnosis_code"
            maxlength="100"
            value="${escapeHtml(
              diagnosis?.diagnosis_code || ""
            )}"
            placeholder="РќРµРѕР±РѕРІ'СЏР·РєРѕРІРѕ"
          >
        </label>

        <label>
          <span>Р”Р°С‚Р° РїРѕСЃС‚Р°РЅРѕРІРєРё</span>
          <input
            type="date"
            name="diagnosed_at"
            value="${escapeHtml(
              dateValue || today
            )}"
          >
        </label>

        <label>
          <span>РџС–РґС‚РІРµСЂРґР¶РµРЅРЅСЏ</span>
          <select name="certainty">
            <option
              value="confirmed"
              ${
                diagnosis?.certainty !==
                "provisional"
                  ? "selected"
                  : ""
              }
            >
              РџС–РґС‚РІРµСЂРґР¶РµРЅРёР№
            </option>
            <option
              value="provisional"
              ${
                diagnosis?.certainty ===
                "provisional"
                  ? "selected"
                  : ""
              }
            >
              РџРѕРїРµСЂРµРґРЅС–Р№
            </option>
          </select>
        </label>

        <label>
          <span>РўСЏР¶РєС–СЃС‚СЊ</span>
          <select name="severity">
            <option value="">РќРµ РІРєР°Р·Р°РЅР°</option>
            ${Object.entries(
              PATIENT_DIAGNOSIS_SEVERITY_LABELS
            )
              .map(
                ([value, label]) => `
                  <option
                    value="${escapeHtml(value)}"
                    ${
                      diagnosis?.severity === value
                        ? "selected"
                        : ""
                    }
                  >
                    ${escapeHtml(label)}
                  </option>
                `
              )
              .join("")}
          </select>
        </label>

        <label>
          <span>РџРѕС‡Р°С‚РѕРє СЃС‚Р°РЅСѓ</span>
          <input
            type="date"
            name="onset_at"
            value="${escapeHtml(
              String(
                diagnosis?.onset_at || ""
              ).slice(0, 10)
            )}"
          >
        </label>

        <label class="is-wide">
          <span>РљР»С–РЅС–С‡РЅР° РїСЂРёРјС–С‚РєР°</span>
          <textarea
            name="clinical_note"
            maxlength="4000"
            rows="4"
            placeholder="РљРѕСЂРѕС‚РєРёР№ РєРѕРЅС‚РµРєСЃС‚, РЅРµ РїРѕРІРЅРёР№ Р·Р°РїРёСЃ РІС–Р·РёС‚Сѓ"
          >${escapeHtml(
            diagnosis?.clinical_note || ""
          )}</textarea>
        </label>

        <div
          class="patientDiagnosisFormError"
          role="alert"
        ></div>

        <footer class="patientDiagnosisFormActions">
          <button
            type="button"
            data-close-diagnosis-modal
          >
            РЎРєР°СЃСѓРІР°С‚Рё
          </button>
          <button
            type="submit"
            class="is-primary"
          >
            ${editing ? "Р—Р±РµСЂРµРіС‚Рё" : "Р”РѕРґР°С‚Рё"}
          </button>
        </footer>
      </form>
    `);

  const form = overlay.querySelector(
    ".patientDiagnosisForm"
  );
  const errorBox = overlay.querySelector(
    ".patientDiagnosisFormError"
  );

  form?.addEventListener(
    "submit",
    async (event) => {
      event.preventDefault();
      errorBox.textContent = "";

      const submitButton =
        form.querySelector(
          "button[type='submit']"
        );
      const data = new FormData(form);
      const payload = {
        diagnosis_name: String(
          data.get("diagnosis_name") || ""
        ).trim(),
        diagnosis_code: String(
          data.get("diagnosis_code") || ""
        ).trim() || null,
        diagnosed_at: String(
          data.get("diagnosed_at") || ""
        ).trim() || null,
        certainty: String(
          data.get("certainty") ||
          "confirmed"
        ),
        severity: String(
          data.get("severity") || ""
        ) || null,
        onset_at: String(
          data.get("onset_at") || ""
        ).trim() || null,
        clinical_note: String(
          data.get("clinical_note") || ""
        ).trim() || null,
      };

      if (!payload.diagnosis_name) {
        errorBox.textContent =
          "Р’РєР°Р¶С–С‚СЊ РЅР°Р·РІСѓ РґС–Р°РіРЅРѕР·Сѓ.";
        return;
      }

      submitButton.disabled = true;
      submitButton.textContent =
        "Р—Р±РµСЂРµР¶РµРЅРЅСЏвЂ¦";

      try {
        if (editing) {
          await updatePatientDiagnosisApi(
            diagnosis.id,
            {
              ...payload,
              version:
                diagnosis.version,
            }
          );
        } else {
          await createPatientDiagnosisApi(
            pet.id,
            payload
          );
        }

        closePatientDiagnosisModal();
        await renderPatientTab(
          "overview",
          pet
        );
      } catch (error) {
        errorBox.textContent =
          error.message ||
          "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р±РµСЂРµРіС‚Рё РґС–Р°РіРЅРѕР·.";
        submitButton.disabled = false;
        submitButton.textContent =
          editing ? "Р—Р±РµСЂРµРіС‚Рё" : "Р”РѕРґР°С‚Рё";
      }
    }
  );
}

async function changePatientDiagnosisStatus(
  pet,
  diagnosis,
  nextStatus
) {
  console.log(
    "DIAGNOSIS STATUS CLICK:",
    nextStatus,
    diagnosis
  );

  const currentStatus =
    String(
      diagnosis?.status ||
      "active"
    )
      .trim()
      .toLowerCase();

  const cleanNextStatus =
    String(
      nextStatus || ""
    )
      .trim()
      .toLowerCase();

  if (
    !cleanNextStatus ||
    currentStatus ===
      cleanNextStatus
  ) {
    return;
  }

  const result =
    await openAppPrompt({
      title:
        cleanNextStatus === "remission"
          ? "РџРµСЂРµРІРµСЃС‚Рё Сѓ СЂРµРјС–СЃС–СЋ"
          : cleanNextStatus === "resolved"
            ? "Р—Р°РІРµСЂС€РёС‚Рё РґС–Р°РіРЅРѕР·"
            : cleanNextStatus === "entered_in_error"
              ? "РџРѕРјРёР»РєРѕРІРёР№ РґС–Р°РіРЅРѕР·"
              : "РџРѕРІРµСЂРЅСѓС‚Рё РІ Р°РєС‚РёРІРЅС–",

      text:
        cleanNextStatus === "entered_in_error"
          ? "Р’РєР°Р¶С–С‚СЊ РїСЂРёС‡РёРЅСѓ, С‡РѕРјСѓ РґС–Р°РіРЅРѕР· С” РїРѕРјРёР»РєРѕРІРёРј."
          : "Р—Р° РїРѕС‚СЂРµР±Рё РІРєР°Р¶С–С‚СЊ РїСЂРёС‡РёРЅСѓ Р·РјС–РЅРё СЃС‚Р°С‚СѓСЃСѓ.",

      label:
        cleanNextStatus === "entered_in_error"
          ? "РџСЂРёС‡РёРЅР° *"
          : "РџСЂРёС‡РёРЅР° Р·РјС–РЅРё СЃС‚Р°С‚СѓСЃСѓ",

      placeholder:
        cleanNextStatus === "entered_in_error"
          ? "РќР°РїСЂРёРєР»Р°Рґ: РґС–Р°РіРЅРѕР· РЅРµ РїС–РґС‚РІРµСЂРґРёРІСЃСЏ"
          : "РќРµРѕР±РѕРІвЂ™СЏР·РєРѕРІРѕ",

      confirmText:
        cleanNextStatus === "remission"
          ? "РЈ СЂРµРјС–СЃС–СЋ"
          : cleanNextStatus === "resolved"
            ? "Р—Р°РІРµСЂС€РёС‚Рё"
            : cleanNextStatus === "entered_in_error"
              ? "РџРѕР·РЅР°С‡РёС‚Рё РїРѕРјРёР»РєРѕРІРёРј"
              : "РџРѕРІРµСЂРЅСѓС‚Рё РІ Р°РєС‚РёРІРЅС–",

      cancelText:
        "РЎРєР°СЃСѓРІР°С‚Рё",

      required:
        cleanNextStatus ===
        "entered_in_error",
    });

  if (result === null) {
    return;
  }

  try {
    await updatePatientDiagnosisApi(
      diagnosis.id,
      {
        version:
          diagnosis.version,

        status:
          cleanNextStatus,

        status_reason:
          String(
            result || ""
          ).trim() || null,
      }
    );

   closePatientDiagnosisModal();

await renderPatientTab(
  "overview",
  pet
);

  } catch (error) {
    showCrmNotice({
      icon: "!",
      title:
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·РјС–РЅРёС‚Рё СЃС‚Р°С‚СѓСЃ",

      text:
        error?.message ||
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·РјС–РЅРёС‚Рё СЃС‚Р°С‚СѓСЃ РґС–Р°РіРЅРѕР·Сѓ.",
    });
  }
}

