function bindPatientDiagnosisPanel(
  root,
  pet,
  diagnoses
) {
  if (!root) return;

  root.querySelector(
    "[data-add-patient-diagnosis]"
  )?.addEventListener(
    "click",
    () => {
      openPatientDiagnosisEditor(
        pet
      );
    }
  );

  root.querySelector(
    "[data-show-diagnosis-history]"
  )?.addEventListener(
    "click",
    () => {
      openPatientDiagnosisHistory(
        pet
      );
    }
  );

  root.querySelector(
    "[data-retry-patient-diagnoses]"
  )?.addEventListener(
    "click",
    () => {
      renderPatientTab(
        "overview",
        pet
      );
    }
  );

  root.querySelectorAll(
    "[data-edit-diagnosis]"
  ).forEach(
    (button) => {
      button.addEventListener(
        "click",
        () => {
          const diagnosis =
            findPatientDiagnosisById(
              diagnoses,
              button.dataset
                .editDiagnosis
            );

          if (!diagnosis) {
            return;
          }

          openPatientDiagnosisEditor(
            pet,
            diagnosis
          );
        }
      );
    }
  );

  root.querySelectorAll(
    "[data-diagnosis-status]"
  ).forEach(
    (button) => {
      button.addEventListener(
        "click",
        async () => {
          const diagnosis =
            findPatientDiagnosisById(
              diagnoses,
              button.dataset
                .diagnosisId
            );

          if (!diagnosis) {
            return;
          }

          await changePatientDiagnosisStatus(
            pet,
            diagnosis,
            button.dataset
              .diagnosisStatus
          );
        }
      );
    }
  );

  root.querySelectorAll(
    "[data-diagnosis-events]"
  ).forEach(
    (button) => {
      button.addEventListener(
        "click",
        () => {
          const diagnosis =
            findPatientDiagnosisById(
              diagnoses,
              button.dataset
                .diagnosisEvents
            );

          if (!diagnosis) {
            return;
          }

          openPatientDiagnosisEvents(
            diagnosis
          );
        }
      );
    }
  );
}

function formatPatientDocumentDate(
  value,
  includeTime = false
) {
  if (!value) return "вЂ”";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return date.toLocaleString(
    "uk-UA",
    includeTime
      ? {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }
      : {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
        }
  );
}

function sanitizePatientDocumentFilename(
  value
) {
  return String(value || "document")
    .trim()
    .replace(/[^\p{L}\p{N}._-]+/gu, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 80) || "document";
}

