function getPetSpeciesKey(pet) {
  const s = String(pet?.species || "").toLowerCase().trim();
  if (s === "cat" || s.includes("РєРѕС‚") || s.includes("РєС–С‚") || s.includes("cat")) return "cat";
  if (s === "dog" || s.includes("РїРµСЃ") || s.includes("СЃРѕР±") || s.includes("dog")) return "dog";
  return "dog";
}

async function loadStaffApi() {
  const maxAttempts = 3;

  const delays = [
    0,
    700,
    1500,
  ];

  let lastError = null;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt++
  ) {
    if (delays[attempt - 1]) {
      await new Promise(
        (resolve) =>
          setTimeout(
            resolve,
            delays[attempt - 1]
          )
      );
    }

    try {
      const response =
        await fetch(
          "/api/staff",
          {
            method: "GET",

            credentials:
              "include",

            cache:
              "no-store",

            headers: {
              Accept:
                "application/json",

              ...getOrgHeaders(),
            },
          }
        );

      const text =
        await response.text();

      let json = null;

      try {
        json =
          text
            ? JSON.parse(text)
            : null;
      } catch {
        json = null;
      }

      if (
        !response.ok ||
        json?.ok !== true
      ) {
        throw new Error(
          json?.error ||
          `HTTP ${response.status}`
        );
      }

      const items =
        Array.isArray(
          json.items
        )
          ? json.items
          : Array.isArray(
              json.data
            )
            ? json.data
            : [];

      state.staff =
        items;

      if (attempt > 1) {
        console.info(
          `loadStaffApi restored on attempt ${attempt}`
        );
      }

      return items;

    } catch (error) {
      lastError =
        error;

      console.warn(
        `loadStaffApi attempt ${attempt}/${maxAttempts} failed:`,
        error
      );
    }
  }

  console.error(
    "loadStaffApi failed after retries:",
    lastError
  );

  const cachedStaff =
    Array.isArray(
      state.staff
    )
      ? state.staff
      : [];

  return cachedStaff;
}

async function loadCalendarApi() {
  try {
    const res =
      await fetch(
        `/api/calendar?_=${Date.now()}`,
        {
          method: "GET",

          credentials:
            "include",

          cache:
            "no-store",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );

    const json =
      await res.json();

    if (!json.ok) {
      throw new Error(
        json.error ||
        "Cannot load calendar"
      );
    }

    return Array.isArray(
      json.items
    )
      ? json.items
      : Array.isArray(
          json.data
        )
        ? json.data
        : [];

  } catch (e) {
    console.error(
      "loadCalendarApi failed:",
      e
    );

    return [];
  }
}

async function loadStaffScheduleApi(date) {
  try {
    const response =
      await fetch(
        `/api/staff-schedule?date=${encodeURIComponent(date)}`,
        {
          method: "GET",
          credentials: "include",

          headers: {
            Accept: "application/json",
            ...getOrgHeaders(),
          },
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      json?.ok !== true
    ) {
      throw new Error(
        json?.error ||
        `HTTP ${response.status}`
      );
    }

    return Array.isArray(json.data)
      ? json.data
      : Array.isArray(json.items)
        ? json.items
        : [];
  } catch (error) {
    console.error(
      "loadStaffScheduleApi failed:",
      error
    );

    return [];
  }
}

async function saveStaffScheduleApi(
  payload
) {
  const maxAttempts = 3;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt += 1
  ) {
    try {
      const response =
        await fetch(
          "/api/staff-schedule",
          {
            method: "POST",

            credentials:
              "include",

            headers: {
              "Content-Type":
                "application/json",

              Accept:
                "application/json",

              ...getOrgHeaders(),
            },

            body:
              JSON.stringify(
                payload || {}
              ),
          }
        );

      const text =
        await response.text();

      let json = null;

      try {
        json = text
          ? JSON.parse(text)
          : null;
      } catch {
        json = null;
      }

      if (
        response.ok &&
        json?.ok === true
      ) {
        return (
          json.data ||
          json.item ||
          null
        );
      }

      const errorMessage =
        json?.error ||
        (
          text &&
          !text.trim().startsWith("<")
            ? text
            : ""
        ) ||
        `HTTP ${response.status}`;

      const retryable =
        response.status === 502 ||
        response.status === 503 ||
        response.status === 504 ||
        String(
          errorMessage
        )
          .toLowerCase()
          .includes(
            "temporarily unavailable"
          ) ||
        String(
          errorMessage
        )
          .toLowerCase()
          .includes(
            "errno 11"
          );

      if (
        retryable &&
        attempt < maxAttempts
      ) {
        await new Promise(
          (resolve) =>
            setTimeout(
              resolve,
              attempt * 500
            )
        );

        continue;
      }

      throw new Error(
        errorMessage
      );

    } catch (error) {
      const errorMessage =
        String(
          error?.message ||
          error ||
          ""
        );

      const retryable =
        errorMessage
          .toLowerCase()
          .includes(
            "temporarily unavailable"
          ) ||
        errorMessage
          .toLowerCase()
          .includes(
            "errno 11"
          ) ||
        errorMessage
          .toLowerCase()
          .includes(
            "failed to fetch"
          ) ||
        error instanceof TypeError;

      if (
        retryable &&
        attempt < maxAttempts
      ) {
        await new Promise(
          (resolve) =>
            setTimeout(
              resolve,
              attempt * 500
            )
        );

        continue;
      }

      console.error(
        "saveStaffScheduleApi failed:",
        error
      );

      alert(
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р±РµСЂРµРіС‚Рё Р·РјС–РЅСѓ: " +
        (
          error?.message ||
          error
        )
      );

      return null;
    }
  }

  return null;
}

async function loadStaffDashboardApi(staffId) {
  try {
    const res = await fetch(`/api/staff/${encodeURIComponent(staffId)}/dashboard`, {
      credentials: "include",
      headers: { Accept: "application/json", ...getOrgHeaders() },
    });

    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok || !json) throw new Error("dashboard failed");

    return json.data || json;
  } catch (e) {
    console.warn("loadStaffDashboardApi error:", e);

    return {
      visits_this_month: 0,
      closed_checks: 0,
      revenue: 0,
      avg_check: 0,
      rating_avg: 0,
      rating: 0,
      revenue_growth_percent: 0,
      visits_growth_percent: 0,
      checks_growth_percent: 0,
      avg_check_growth_percent: 0,
      last_visits: [],
      revenue_chart: [],
      visits_chart: [],
      penalties: {
        late: 0,
        absences: 0,
        warnings: 0,
        bonuses_amount: 0,
        penalties_amount: 0
      }
    };
  }
}
