  $$("[data-calendar-timeline]")
  .forEach(
    (timeline) => {
      const hover =
        timeline.querySelector(
          ".calendarTimelineHover"
        );

      const hoverTime =
  hover?.querySelector("b");

const staffId =
  String(
    timeline.dataset
      .staffId ||
    ""
  );

const timelineScheduleRow =
  staffSchedule.find(
    (item) =>
      String(
        item.staff_id
      ) ===
      String(
        staffId
      )
  ) || null;

const timelineShiftStart =
  String(
    timelineScheduleRow?.start_time ||
    ""
  ).slice(0, 5);

const timelineShiftEnd =
  String(
    timelineScheduleRow?.end_time ||
    ""
  ).slice(0, 5);

const isTimelineTimeInsideShift = (
  time
) => {
  const cleanTime =
    String(
      time || ""
    ).slice(0, 5);

  return Boolean(
    timelineScheduleRow &&
    timelineScheduleRow
      .is_active !== false &&
    timelineShiftStart &&
    timelineShiftEnd &&
    cleanTime >=
      timelineShiftStart &&
    cleanTime <
      timelineShiftEnd
  );
};

      const getTimeFromPointer = (
        event
      ) => {
        const rect =
          timeline
            .getBoundingClientRect();

        const localY =
          Math.max(
            0,
            Math.min(
              event.clientY -
                rect.top,
              rect.height
            )
          );

        const rawMinutes =
          calendarDayStartMinutes +
          localY /
            calendarHourHeight *
            60;

        const roundedMinutes =
          Math.round(
            rawMinutes / 15
          ) * 15;

        const safeMinutes =
          Math.max(
            calendarDayStartMinutes,
            Math.min(
              roundedMinutes,
              calendarDayEndMinutes -
                15
            )
          );

        const hoursValue =
          Math.floor(
            safeMinutes / 60
          );

        const minutesValue =
          safeMinutes % 60;

        return {
          minutes:
            safeMinutes,

          time:
            `${String(
              hoursValue
            ).padStart(
              2,
              "0"
            )}:${String(
              minutesValue
            ).padStart(
              2,
              "0"
            )}`,

          top:
            (
              safeMinutes -
              calendarDayStartMinutes
            ) /
            60 *
            calendarHourHeight,
        };
      };

      timeline.addEventListener(
        "mousemove",
        (event) => {
          if (
            event.target.closest(
              "[data-edit-calendar-event]"
            )
          ) {
            if (hover) {
              hover.hidden =
                true;
            }

            return;
          }

          const pointerTime =
  getTimeFromPointer(
    event
  );

if (
  !isTimelineTimeInsideShift(
    pointerTime.time
  )
) {
  if (hover) {
    hover.hidden =
      true;
  }

  return;
}

if (hover) {
  hover.hidden =
    false;

  hover.style.top =
    `${pointerTime.top}px`;
}

if (hoverTime) {
  hoverTime.textContent =
    pointerTime.time;
}
}
);

      timeline.addEventListener(
        "mouseleave",
        () => {
          if (hover) {
            hover.hidden =
              true;
          }
        }
      );

      timeline.addEventListener(
        "click",
        (event) => {
          if (
            event.target.closest(
              "[data-edit-calendar-event]"
            ) ||
            event.target.closest(
              "[data-del-calendar-event]"
            )
          ) {
            return;
          }

          const pointerTime =
  getTimeFromPointer(
    event
  );

if (
  !staffId ||
  !pointerTime.time
) {
  return;
}

if (
  !isTimelineTimeInsideShift(
    pointerTime.time
  )
) {
  return;
}

openVisitFromCalendar(
  pointerTime.time,
  staffId
);
        }
      );

      timeline.addEventListener(
        "dragover",
        (event) => {
          event.preventDefault();

          timeline.classList.add(
            "is-drag-over"
          );

          const pointerTime =
  getTimeFromPointer(
    event
  );
if (
  !isTimelineTimeInsideShift(
    pointerTime.time
  )
) {
  timeline.classList.remove(
    "is-drag-over"
  );

  if (hover) {
    hover.hidden = true;
  }

  return;
}  

if (hover) {
  hover.hidden =
    false;

  hover.style.top =
    `${pointerTime.top}px`;
}

if (hoverTime) {
  hoverTime.textContent =
    pointerTime.time;
}
}
);

timeline.addEventListener(
  "dragleave",
  (event) => {
    if (
      timeline.contains(
        event.relatedTarget
      )
    ) {
      return;
    }

    timeline.classList.remove(
      "is-drag-over"
    );

    if (hover) {
      hover.hidden =
        true;
    }
  }
);

timeline.addEventListener(
  "drop",
  (event) => {
    event.preventDefault();

    timeline.classList.remove(
      "is-drag-over"
    );

    if (hover) {
      hover.hidden =
        true;
    }

    let dragData =
      null;

    try {
      dragData =
        JSON.parse(
          event.dataTransfer
            .getData(
              "text/plain"
            ) ||
          "{}"
        );
    } catch {
      return;
    }

    const droppedStaffId =
      String(
        dragData?.staff_id ||
        staffId ||
        ""
      );

    if (!droppedStaffId) {
      return;
    }

    const pointerTime =
  getTimeFromPointer(
    event
  );

if (!pointerTime.time) {
  return;
}

if (
  !isTimelineTimeInsideShift(
    pointerTime.time
  )
) {
  return;
}

openVisitFromCalendar(
  pointerTime.time,
  droppedStaffId
);
  }
);
}
);

