async function loadSpecializationsApi() {
  try {
    const res = await fetch("/api/specializations");
    const json = await res.json();
    if (!json.ok) throw new Error(json.error || "Cannot load specializations");
    return Array.isArray(json.data) ? json.data : [];
  } catch (e) {
    console.error("loadSpecializationsApi failed:", e);
    return [];
  }
}

async function createSpecializationApi(payload) {
  try {
    const res = await fetch("/api/specializations", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload || {}),
    });
    const json = await res.json();

    if (!json.ok) {
      alert(json.error || "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё РЅР°РїСЂСЏРј");
      return null;
    }
    return Array.isArray(json.data)
  ? json.data[0] || null
  : json.data || null;
  } catch (e) {
    console.error("createSpecializationApi failed:", e);
    alert("РџРѕРјРёР»РєР° СЃС‚РІРѕСЂРµРЅРЅСЏ РЅР°РїСЂСЏРјСѓ");
    return null;
  }
}

async function deleteSpecializationApi(specializationId) {
  const cleanId = String(
    specializationId || ""
  ).trim();

  if (!cleanId) {
    return {
      ok: false,
      error: "РќРµ РІРєР°Р·Р°РЅРѕ РЅР°РїСЂСЏРј.",
    };
  }

  try {
    const response = await fetch(
      `/api/specializations/${encodeURIComponent(cleanId)}`,
      {
        method: "DELETE",
        credentials: "include",
        headers: {
          Accept: "application/json",
        },
      }
    );

    const json = await response.json();

    if (!response.ok || !json?.ok) {
      return {
        ok: false,
        error:
          json?.error ||
          "РќРµ РІРґР°Р»РѕСЃСЏ РІРёРґР°Р»РёС‚Рё РЅР°РїСЂСЏРј.",
      };
    }

    return { ok: true };
  } catch (error) {
    console.error(
      "deleteSpecializationApi failed:",
      error
    );

    return {
      ok: false,
      error:
        "РџРѕРјРёР»РєР° Р·'С”РґРЅР°РЅРЅСЏ РїС–Рґ С‡Р°СЃ РІРёРґР°Р»РµРЅРЅСЏ РЅР°РїСЂСЏРјСѓ.",
    };
  }
}

async function createStaffApi(payload) {
  try {
    const res = await fetch("/api/staff", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const json = await res.json();

    if (!json.ok) {
      alert(json.error || "РџРѕРјРёР»РєР° СЃС‚РІРѕСЂРµРЅРЅСЏ РІРµС‚РµСЂРёРЅР°СЂР°");
      return null;
    }
    return json.data || null;
  } catch (e) {
    console.error(e);
    alert("РџРѕРјРёР»РєР° СЃС‚РІРѕСЂРµРЅРЅСЏ РІРµС‚РµСЂРёРЅР°СЂР°");
    return null;
  }
}
function getCalendarCreateErrorMessage(
  errorText = ""
) {
  const raw =
    String(errorText || "")
      .trim()
      .toLowerCase();

  if (
    raw === "time slot busy"
  ) {
    return "Р¦РµР№ С‡Р°СЃ РІР¶Рµ Р·Р°Р№РЅСЏС‚РёР№ Сѓ РІРёР±СЂР°РЅРѕРіРѕ Р»С–РєР°СЂСЏ.";
  }

  if (
  raw ===
  "end_time must be later than start_time"
) {
  return "Р—РјС–РЅР° Р»С–РєР°СЂСЏ РЅР° СЃСЊРѕРіРѕРґРЅС– РІР¶Рµ Р·Р°РІРµСЂС€РµРЅР°. РћР±РµСЂС–С‚СЊ СЂР°РЅС–С€РёР№ С‡Р°СЃ РїСЂРёР№РѕРјСѓ Р°Р±Рѕ РїРµСЂРµРЅРµСЃС–С‚СЊ Р·Р°РїРёСЃ РЅР° РЅР°СЃС‚СѓРїРЅРёР№ РґРµРЅСЊ.";
}

  return (
    String(errorText || "")
      .trim() ||
    "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё Р·Р°РїРёСЃ."
  );
}
async function createCalendarEventApi(payload) {
  try {
    const res = await fetch("/api/calendar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload || {}),
    });
    const json = await res.json();

    if (!json.ok) {
  showCrmNotice({
    icon: "вљ ",
    title: "РќРµ РІРґР°Р»РѕСЃСЏ СЃС‚РІРѕСЂРёС‚Рё Р·Р°РїРёСЃ",
    text: getCalendarCreateErrorMessage(
      json.error
    ),
  });

  return null;
}
    return json.data || json.item || null;
  } catch (e) {
    console.error("createCalendarEventApi failed:", e);
    showCrmNotice({
  icon: "вљ ",
  title: "РџРѕРјРёР»РєР° СЃС‚РІРѕСЂРµРЅРЅСЏ Р·Р°РїРёСЃСѓ",
  text:
    "РЎС‚Р°Р»Р°СЃСЏ РїРѕРјРёР»РєР° РїС–Рґ С‡Р°СЃ СЃС‚РІРѕСЂРµРЅРЅСЏ Р·Р°РїРёСЃСѓ. " +
    (e?.message || e || ""),
});
    return null;
  }
}

async function updateCalendarEventApi(eventId, payload) {
  try {
    const res = await fetch(`/api/calendar/${encodeURIComponent(eventId)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload || {}),
    });
    const json = await res.json();

    if (!json.ok) {
      alert("РќРµ РІРґР°Р»РѕСЃСЏ РѕРЅРѕРІРёС‚Рё Р·Р°РїРёСЃ: " + (json.error || "unknown error"));
      return null;
    }
    return json.data || json.item || null;
  } catch (e) {
    console.error("updateCalendarEventApi failed:", e);
    alert("РџРѕРјРёР»РєР° РѕРЅРѕРІР»РµРЅРЅСЏ Р·Р°РїРёСЃСѓ: " + (e?.message || e));
    return null;
  }
}

