// =========================
async function syncCalendarEventStatusByVisitId(
  visitId,
  nextStatus
) {
  const cleanVisitId =
    String(
      visitId || ""
    ).trim();

  const cleanStatus =
    String(
      nextStatus || ""
    )
      .trim()
      .toLowerCase();

  if (!cleanVisitId) {
    throw new Error(
      "РќРµ РІРєР°Р·Р°РЅРѕ ID РјРµРґРёС‡РЅРѕРіРѕ РІС–Р·РёС‚Сѓ."
    );
  }

  if (!cleanStatus) {
    throw new Error(
      "РќРµ РІРєР°Р·Р°РЅРѕ РЅРѕРІРёР№ СЃС‚Р°С‚СѓСЃ РєР°Р»РµРЅРґР°СЂСЏ."
    );
  }

  const calendarEvents =
    await loadCalendarApi();

  const allEvents =
    Array.isArray(
      calendarEvents
    )
      ? calendarEvents
      : [];

  const cachedVisit =
    getVisitByIdSync(
      cleanVisitId
    );

  const cachedCalendarEventId =
    String(
      cachedVisit
        ?.calendar_event_id ||
      ""
    ).trim();

  let linkedEvents =
    allEvents.filter(
      (event) =>
        String(
          event?.visit_id || ""
        ).trim() ===
        cleanVisitId
    );

  if (
    !linkedEvents.length &&
    cachedCalendarEventId
  ) {
    linkedEvents =
      allEvents.filter(
        (event) =>
          String(
            event?.id || ""
          ).trim() ===
          cachedCalendarEventId
      );
  }

  if (!linkedEvents.length) {
    console.error(
      "РќРµ Р·РЅР°Р№РґРµРЅРѕ РєР°Р»РµРЅРґР°СЂРЅРёР№ Р·Р°РїРёСЃ РґР»СЏ РІС–Р·РёС‚Сѓ:",
      {
        visitId:
          cleanVisitId,

        cachedCalendarEventId,

        calendarEvents:
          allEvents,
      }
    );

    throw new Error(
      (
        "РњРµРґРёС‡РЅС– РґР°РЅС– Р·Р±РµСЂРµР¶РµРЅРѕ, " +
        "Р°Р»Рµ РєР°Р»РµРЅРґР°СЂРЅРёР№ Р·Р°РїРёСЃ, " +
        "РїРѕРІвЂ™СЏР·Р°РЅРёР№ С–Р· РІС–Р·РёС‚РѕРј, " +
        "РЅРµ Р·РЅР°Р№РґРµРЅРѕ."
      )
    );
  }

  const updatedEvents =
    [];

  for (
    const linkedEvent
    of linkedEvents
  ) {
    const updated =
      await updateCalendarEventApi(
        linkedEvent.id,
        {
          title:
            linkedEvent.title ||
            "РџСЂРёР№РѕРј",

          event_date:
            linkedEvent.event_date,

          start_time:
            linkedEvent.start_time,

          end_time:
            linkedEvent.end_time,

          staff_id:
            linkedEvent.staff_id,

          patient_id:
            linkedEvent.patient_id ||
            null,

          owner_id:
            linkedEvent.owner_id ||
            null,

          visit_id:
            cleanVisitId,

          location:
            linkedEvent.location ||
            "",

          note:
            linkedEvent.note ||
            "",

          status:
            cleanStatus,
        }
      );

    if (!updated?.id) {
      throw new Error(
        (
          "РЎРµСЂРІРµСЂ РЅРµ РїС–РґС‚РІРµСЂРґРёРІ " +
          "РѕРЅРѕРІР»РµРЅРЅСЏ РєР°Р»РµРЅРґР°СЂРЅРѕРіРѕ Р·Р°РїРёСЃСѓ."
        )
      );
    }

    const returnedStatus =
      String(
        updated.status || ""
      )
        .trim()
        .toLowerCase();

    if (
      returnedStatus !==
      cleanStatus
    ) {
      console.error(
        "Calendar status was not saved:",
        {
          expected:
            cleanStatus,

          returned:
            returnedStatus,

          event:
            updated,
        }
      );

      throw new Error(
        (
          "РЎРµСЂРІРµСЂ РїРѕРІРµСЂРЅСѓРІ РєР°Р»РµРЅРґР°СЂРЅРёР№ Р·Р°РїРёСЃ, " +
          "Р°Р»Рµ РЅРµ Р·Р±РµСЂС–Рі СЃС‚Р°С‚СѓСЃ В«Р—Р°РІРµСЂС€РµРЅРѕВ»."
        )
      );
    }

    updatedEvents.push(
      updated
    );
  }

  const primaryEvent =
    updatedEvents.find(
      (event) =>
        String(
          event.id || ""
        ) ===
        cachedCalendarEventId
    ) ||
    updatedEvents[0];

  const mergedVisit = {
    ...(cachedVisit || {}),

    calendar_event_id:
      primaryEvent?.id ||
      cachedCalendarEventId ||
      null,

    calendar_status:
      cleanStatus,
  };

  cacheVisits([
    mergedVisit,
  ]);

  console.log(
    "РљР°Р»РµРЅРґР°СЂРЅС– Р·Р°РїРёСЃРё СЃРёРЅС…СЂРѕРЅС–Р·РѕРІР°РЅРѕ:",
    {
      visitId:
        cleanVisitId,

      status:
        cleanStatus,

      updatedEventIds:
        updatedEvents.map(
          (event) =>
            event.id
        ),
    }
  );

  return primaryEvent;
}
