function parseVisitNote(note) {
  const t =
    String(
      note || ""
    );

  const dxMatch =
    t.match(
      /Р”С–Р°РіРЅРѕР·:\s*(.*?)(\n|$)/i
    );

  const dx =
    (
      dxMatch?.[1] || ""
    ).trim();

  const compMatch =
    t.match(
      /РЎРєР°СЂРіРё\/Р°РЅР°РјРЅРµР·:\s*([\s\S]*)/i
    );

  const complaint =
    (
      compMatch?.[1] || ""
    ).trim();

  return {
    dx:
      dx || "",

    complaint:
      complaint ||
      (
        !dx
          ? t.trim()
          : ""
      ),
  };
}


function parseVisitRx(value) {
  const text = String(value || "").trim();

  const marker =
    "\n\nР РµРєРѕРјРµРЅРґР°С†С–С— РІР»Р°СЃРЅРёРєСѓ:\n";

  const markerIndex =
    text.indexOf(marker);

  if (markerIndex === -1) {
    return {
      rx: text,
      recommendation: "",
    };
  }

  return {
    rx: text
      .slice(0, markerIndex)
      .replace(/^Р›С–РєСѓРІР°РЅРЅСЏ:\s*/i, "")
      .trim(),

    recommendation: text
      .slice(markerIndex + marker.length)
      .trim(),
  };
}


function buildVisitRx(
  rx,
  recommendation
) {
  const treatment =
    String(rx || "").trim();

  const clientRecommendation =
    String(recommendation || "").trim();

  if (!clientRecommendation) {
    return treatment;
  }

  return [
    treatment
      ? `Р›С–РєСѓРІР°РЅРЅСЏ:\n${treatment}`
      : "Р›С–РєСѓРІР°РЅРЅСЏ:\nвЂ”",

    `Р РµРєРѕРјРµРЅРґР°С†С–С— РІР»Р°СЃРЅРёРєСѓ:\n${clientRecommendation}`,
  ].join("\n\n");
}
