function initVisitNewPatientBreedPicker() {
  const speciesSelect =
    document.querySelector(
      "#visitNewPetSpecies"
    );

  const breedInput =
    document.querySelector(
      "#visitNewPetBreed"
    );

  const breedList =
    document.querySelector(
      "#visitNewPetBreedList"
    );

  const breedLabel =
    document.querySelector(
      "#visitNewPetBreedLabel"
    );

  if (
    !speciesSelect ||
    !breedInput ||
    !breedList
  ) {
    return;
  }

  const renderBreedOptions = () => {
    const species =
      String(
        speciesSelect.value || ""
      ).trim();

    let breeds = [];

    breedInput.value = "";
    breedList.innerHTML = "";

    if (species === "dog") {
      breeds = DOG_BREEDS;

      breedInput.disabled = false;

      breedInput.placeholder =
        "РџРѕС‡РЅС–С‚СЊ РІРІРѕРґРёС‚Рё РїРѕСЂРѕРґСѓ СЃРѕР±Р°РєРё";

      if (breedLabel) {
        breedLabel.textContent =
          "РџРѕСЂРѕРґР° СЃРѕР±Р°РєРё";
      }
    } else if (species === "cat") {
      breeds = CAT_BREEDS;

      breedInput.disabled = false;

      breedInput.placeholder =
        "РџРѕС‡РЅС–С‚СЊ РІРІРѕРґРёС‚Рё РїРѕСЂРѕРґСѓ РєРѕС‚Р°";

      if (breedLabel) {
        breedLabel.textContent =
          "РџРѕСЂРѕРґР° РєРѕС‚Р°";
      }
    } else if (species === "other") {
  breeds =
    OTHER_SPECIES_LIST;

  breedInput.disabled =
    false;

  breedInput.placeholder =
    "РћР±РµСЂС–С‚СЊ Р°Р±Рѕ РїРѕС‡РЅС–С‚СЊ РІРІРѕРґРёС‚Рё РІРёРґ С‚РІР°СЂРёРЅРё";

  if (breedLabel) {
    breedLabel.textContent =
      "Р’РёРґ С‚РІР°СЂРёРЅРё";
  }
} else {
      breedInput.disabled = true;

      breedInput.placeholder =
        "РЎРїРѕС‡Р°С‚РєСѓ РѕР±РµСЂС–С‚СЊ РІРёРґ";

      if (breedLabel) {
        breedLabel.textContent =
          "РџРѕСЂРѕРґР°";
      }
    }

    breedList.innerHTML =
      breeds
        .map(
          (breed) => `
            <option
              value="${escapeHtml(breed)}"
            ></option>
          `
        )
        .join("");
  };

  speciesSelect.addEventListener(
    "change",
    renderBreedOptions
  );

  renderBreedOptions();
}

initVisitNewPatientBreedPicker();

