// =====================================================
// REGISTRATION VACCINE SELECTS
// =====================================================

const fillRegistrationVaccineSelect =
  (
    select,
    coverageTag
  ) => {
    if (!select) {
      return;
    }


    const previousValue =
      String(
        select.value || ""
      );


    const species =
      String(
        speciesInput?.value || ""
      ).trim();


    const brands =
      getVaccineBrandsForPatient({
        species,
      });


    const vaccines = [];


    brands.forEach(
      (brand) => {
        (
          Array.isArray(
            brand.vaccines
          )
            ? brand.vaccines
            : []
        ).forEach(
          (vaccine) => {
            const coverage =
              getVaccineCoverageTags(
                brand,
                vaccine
              );


            if (
              !coverage.includes(
                coverageTag
              )
            ) {
              return;
            }


            vaccines.push({
              brand,
              vaccine,
            });
          }
        );
      }
    );


    select.innerHTML = `
      <option value="">
        ${
          species
            ? "РћР±РµСЂС–С‚СЊ РІР°РєС†РёРЅСѓ"
            : "РЎРїРѕС‡Р°С‚РєСѓ РѕР±РµСЂС–С‚СЊ РІРёРґ"
        }
      </option>

      ${
        vaccines
          .map(
            ({
              brand,
              vaccine,
            }) => {
              const value =
                `${brand.brand}|||${vaccine.name}`;

              const label = [
                brand.flag || "",
                brand.brand || "",
                vaccine.name || "",
              ]
                .filter(Boolean)
                .join(" ");

              return `
                <option
                  value="${escapeHtml(
                    value
                  )}"
                >
                  ${escapeHtml(
                    label
                  )}
                </option>
              `;
            }
          )
          .join("")
      }
    `;


    select.disabled =
      !species ||
      vaccines.length === 0;


    if (
      previousValue &&
      Array.from(
        select.options
      ).some(
        (option) =>
          option.value ===
          previousValue
      )
    ) {
      select.value =
        previousValue;
    }
  };


// =====================================================
// REFRESH BOTH VACCINE LISTS
// =====================================================

const refreshRegistrationVaccineSelects =
  () => {
    fillRegistrationVaccineSelect(
      rabiesVaccineInput,
      "rabies"
    );


    fillRegistrationVaccineSelect(
      generalVaccineInput,
      "general"
    );
  };


// =====================================================
// SHOW / HIDE VACCINATION DETAILS
// =====================================================

const syncRegistrationVaccination =
  () => {
    const rabiesVaccinated =
      rabiesStatusInput?.value ===
      "vaccinated";


    const generalVaccinated =
      generalVaccinationStatusInput
        ?.value ===
      "vaccinated";


    if (rabiesDetails) {
      rabiesDetails.hidden =
        !rabiesVaccinated;
    }


    if (
      generalVaccinationDetails
    ) {
      generalVaccinationDetails.hidden =
        !generalVaccinated;
    }


    if (
      rabiesVaccinated &&
      rabiesDateInput &&
      !rabiesDateInput.value
    ) {
      rabiesDateInput.value =
        todayISO();
    }


    if (
      generalVaccinated &&
      generalVaccinationDateInput &&
      !generalVaccinationDateInput
        .value
    ) {
      generalVaccinationDateInput.value =
        todayISO();
    }


    if (rabiesDateInput) {
      rabiesDateInput.required =
        rabiesVaccinated;
    }


    if (rabiesVaccineInput) {
      rabiesVaccineInput.required =
        rabiesVaccinated;
    }


    if (
      generalVaccinationDateInput
    ) {
      generalVaccinationDateInput.required =
        generalVaccinated;
    }


    if (generalVaccineInput) {
      generalVaccineInput.required =
        generalVaccinated;
    }
  };


