function initOwnerUI() {
  // Р”РѕР±Р°РІР»РµРЅРёРµ Р¶РёРІРѕС‚РЅРѕРіРѕ РІР»Р°РґРµР»СЊС†Сѓ
  $("#btnAddPet")?.addEventListener("click", () => {
    const ownerId = state.selectedOwnerId;

    if (!ownerId) {
      alert("РЎРїРѕС‡Р°С‚РєСѓ РѕР±РµСЂРё РІР»Р°СЃРЅРёРєР°");
      return;
    }

    openAddPetModal(ownerId);
  });

  // РљР»РёРє РїРѕ СЃРїРёСЃРєСѓ Р¶РёРІРѕС‚РЅС‹С… (РЈРґР°Р»РµРЅРёРµ / РћС‚РєСЂС‹С‚РёРµ)
  $("#petsList")?.addEventListener(
  "click",
  async (e) => {
    const editBtn =
      e.target.closest(
        "[data-edit-owner-pet]"
      );

    if (editBtn) {
      e.preventDefault();
      e.stopPropagation();

      const petId =
        editBtn.dataset
          .editOwnerPet;

      if (!petId) {
        return;
      }

      const pet =
        (
          state.patients || []
        ).find(
          (item) =>
            String(item.id) ===
            String(petId)
        );

      if (!pet) {
        openDeleteModal(
          "РџР°С†С–С”РЅС‚Р° РЅРµ Р·РЅР°Р№РґРµРЅРѕ.",
          null,
          "info"
        );

        return;
      }

      openAddPetModal(
        pet.owner_id,
        pet
      );

      return;
    }

    const delBtn =
      e.target.closest(
        "[data-del-pet]"
      );

    if (delBtn) {
      e.preventDefault();
      e.stopPropagation();

      const petId =
        delBtn.dataset
          .delPet;

      if (!petId) {
        return;
      }

      const pet =
        (
          state.patients || []
        ).find(
          (item) =>
            String(item.id) ===
            String(petId)
        );

      const petName =
        pet?.name ||
        "С†СЊРѕРіРѕ РїР°С†С–С”РЅС‚Р°";

      openDeleteModal(
        `
          <b>
            ${escapeHtml(petName)}
          </b>
          <br><br>
          Р¦СЋ РґС–СЋ РЅРµРјРѕР¶Р»РёРІРѕ СЃРєР°СЃСѓРІР°С‚Рё.
        `,
        async () => {
          const ok =
            await deletePatientApi(
              petId
            );

          if (!ok) {
            openDeleteModal(
              "РќРµ РІРґР°Р»РѕСЃСЏ РІРёРґР°Р»РёС‚Рё РїР°С†С–С”РЅС‚Р°.",
              null,
              "info"
            );

            return;
          }

          await loadPatientsApi();

          if (
            String(
              state.selectedPetId ||
              ""
            ) ===
            String(petId)
          ) {
            state.selectedPetId =
              null;

            state.selectedPet =
              null;
          }

          if (
            state.selectedOwnerId
          ) {
            await renderOwnerPage(
              state.selectedOwnerId
            );
          }
        }
      );

      return;
    }

    const openZone =
      e.target.closest(
        "[data-open-pet]"
      );

    if (openZone) {
      const petId =
        openZone.dataset
          .openPet;

      if (petId) {
        openPatient(
          petId
        );
      }
    }
  }
);
}
