// =========================
// РЎРїРµС†РёС„РёРєР°С†РёРё РІРёРґРѕРІ Р¶РёРІРѕС‚РЅС‹С… Рё РЅРѕСЂРјР°Р»РёР·Р°С‚РѕСЂС‹
// =========================
function normalizeSpecies(value) {
  const s = String(value || "")
    .toLowerCase()
    .trim();

  if (
    s === "dog" ||
    s.includes("РїРµСЃ") ||
    s.includes("СЃРѕР±") ||
    s.includes("dog")
  ) {
    return "dog";
  }

  if (
    s === "cat" ||
    s.includes("РєРѕС‚") ||
    s.includes("РєС–С‚") ||
    s.includes("cat")
  ) {
    return "cat";
  }

  return "dog";
}

function speciesLabel(value) {
  const key = normalizeSpecies(value);

  if (key === "cat") {
    return "РєС–С‚";
  }

  return "РїРµСЃ";
}

function askSpecies(current = "dog") {
  const cur = normalizeSpecies(current);

  const raw = prompt(
    "Р’РёРґ РїР°С†С–С”РЅС‚Р°:\n1 вЂ” РїРµСЃ\n2 вЂ” РєС–С‚",
    cur === "cat" ? "2" : "1"
  );

  if (raw === null) {
    return null;
  }

  const value = String(raw)
    .trim()
    .toLowerCase();

  if (
    value === "2" ||
    value === "cat" ||
    value.includes("РєРѕС‚") ||
    value.includes("РєС–С‚")
  ) {
    return "cat";
  }

  return "dog";
}


