function formatAuditDate(value) {
  if (!value) return "вЂ”";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return date.toLocaleString(
    "uk-UA",
    {
      dateStyle: "medium",
      timeStyle: "short",
    }
  );
}


function renderAuditJson(value) {
  if (
    value == null ||
    (
      typeof value === "object" &&
      Object.keys(value).length === 0
    )
  ) {
    return "вЂ”";
  }

  try {
    return escapeHtml(
      JSON.stringify(
        value,
        null,
        2
      )
    );
  } catch {
    return escapeHtml(
      String(value)
    );
  }
}


async function loadAuditEventsApi(
  filters = {}
) {
  const params =
    new URLSearchParams();

  params.set(
    "limit",
    String(AUDIT_EVENTS_PAGE_SIZE)
  );

  params.set(
    "offset",
    String(
      Math.max(
        0,
        Number(filters.offset) || 0
      )
    )
  );

  [
    "action",
    "actor_name",
    "date_from",
    "date_to",
  ].forEach((key) => {
    const value =
      String(filters[key] || "").trim();

    if (value) {
      params.set(key, value);
    }
  });

  const response = await fetch(
    `/api/audit-events?${params.toString()}`,
    {
      method: "GET",
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    }
  );

  const text = await response.text();
  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {}

  if (
    !response.ok ||
    json?.ok !== true
  ) {
    throw new Error(
      json?.error ||
      "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё Р¶СѓСЂРЅР°Р» РґС–Р№."
    );
  }

  return json.data || {
    events: [],
    total: 0,
    limit: AUDIT_EVENTS_PAGE_SIZE,
    offset: 0,
  };
}


