async function refreshAuditEvents(
  page,
  { reset = false } = {}
) {
  if (reset) {
    auditViewState.offset = 0;
  }

  const results =
    page.querySelector(
      "#auditEventsResult"
    );

  if (!results) return;

  results.innerHTML = `
    <div class="auditEventsLoading">
      Р—Р°РІР°РЅС‚Р°Р¶СѓС”РјРѕ Р¶СѓСЂРЅР°Р» РґС–Р№вЂ¦
    </div>
  `;

  const filters = {
    offset: auditViewState.offset,
    action:
      page.querySelector(
        "#auditActionFilter"
      )?.value || "",
    actor_name:
      page.querySelector(
        "#auditActorFilter"
      )?.value || "",
    date_from:
      page.querySelector(
        "#auditDateFrom"
      )?.value || "",
    date_to:
      page.querySelector(
        "#auditDateTo"
      )?.value || "",
  };

  try {
    const data =
      await loadAuditEventsApi(
        filters
      );

    auditViewState.offset =
      Number(data?.offset) || 0;

    renderAuditEventsResult(
      page,
      data
    );

  } catch (error) {
    results.innerHTML = `
      <div class="auditEventsError">
        ${escapeHtml(
          error?.message ||
          "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё Р¶СѓСЂРЅР°Р»."
        )}
      </div>
    `;
  }
}


