function bindClinicProfileSettings(page, clinic) {
  const form =
    page.querySelector("#clinicProfileForm");

  if (!form) return;

  const colorPicker =
    page.querySelector(
      "#clinicProfileAccentColor"
    );

  const colorText =
    page.querySelector(
      "#clinicProfileAccentText"
    );

  colorPicker?.addEventListener("input", () => {
    if (colorText) {
      colorText.value =
        colorPicker.value.toUpperCase();
    }

    updateClinicDocumentPreview(page);
  });

  colorText?.addEventListener("input", () => {
    const value =
      String(colorText.value || "")
        .trim()
        .toUpperCase();

    if (/^#[0-9A-F]{6}$/.test(value)) {
      if (colorPicker) {
        colorPicker.value = value;
      }

      updateClinicDocumentPreview(page);
    }
  });

  form
    .querySelectorAll(
      "input:not([type='file']):not([type='hidden'])"
    )
    .forEach((input) => {
      input.addEventListener(
        "input",
        () => updateClinicDocumentPreview(page)
      );
    });

  form
    .querySelectorAll("[data-brand-file]")
    .forEach((input) => {
      input.addEventListener(
        "change",
        async () => {
          const type =
            input.dataset.brandFile;

          const file =
            input.files?.[0];

          if (!type || !file) return;

          const uploadBlock =
            input.closest(".clinicBrandUpload");

          uploadBlock?.classList.add(
            "uploading"
          );

          try {
            const url =
              await uploadClinicBrandFile(file);

            const hidden =
              page.querySelector(
                `[data-brand-url="${type}"]`
              );

            if (hidden) {
              hidden.value = url;
            }

            const preview =
              page.querySelector(
                `[data-brand-preview="${type}"]`
              );

            if (preview) {
              preview.innerHTML = `
                <img
                  src="${escapeHtml(url)}"
                  alt=""
                >
              `;
            }

            updateClinicDocumentPreview(page);
          } catch (error) {
            alert(
              "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё С„Р°Р№Р»: " +
              (error?.message || error)
            );
          } finally {
            uploadBlock?.classList.remove(
              "uploading"
            );

            input.value = "";
          }
        }
      );
    });

  form
    .querySelectorAll("[data-brand-remove]")
    .forEach((button) => {
      button.addEventListener(
        "click",
        () => {
          const type =
            button.dataset.brandRemove;

          const hidden =
            page.querySelector(
              `[data-brand-url="${type}"]`
            );

          if (hidden) {
            hidden.value = "";
          }

          const preview =
            page.querySelector(
              `[data-brand-preview="${type}"]`
            );

          if (preview) {
            preview.innerHTML = "<span>пј‹</span>";
          }

          updateClinicDocumentPreview(page);
        }
      );
    });

  form.addEventListener(
    "submit",
    async (event) => {
      event.preventDefault();

      const saveButton =
        page.querySelector(
          "#btnSaveClinicProfile"
        );

      const status =
        page.querySelector(
          "#clinicProfileSaveStatus"
        );

      const payload = {
        name:
          page
            .querySelector("#clinicProfileName")
            ?.value?.trim() || "",

        subtitle:
          page
            .querySelector(
              "#clinicProfileSubtitle"
            )
            ?.value?.trim() || "",

        phone:
          page
            .querySelector(
              "#clinicProfilePhone"
            )
            ?.value?.trim() || "",

        address:
          page
            .querySelector(
              "#clinicProfileAddress"
            )
            ?.value?.trim() || "",

        website:
          page
            .querySelector(
              "#clinicProfileWebsite"
            )
            ?.value?.trim() || "",

        document_accent_color:
          page
            .querySelector(
              "#clinicProfileAccentText"
            )
            ?.value?.trim()
            .toUpperCase() || "#9346E8",

        document_footer:
          page
            .querySelector(
              "#clinicProfileFooter"
            )
            ?.value?.trim() || "",

        logo_url:
          page
            .querySelector(
              '[data-brand-url="logo"]'
            )
            ?.value || "",

        doctor_signature_url:
          page
            .querySelector(
              '[data-brand-url="signature"]'
            )
            ?.value || "",

        clinic_stamp_url:
          page
            .querySelector(
              '[data-brand-url="stamp"]'
            )
            ?.value || "",
      };

      if (!payload.name) {
        alert("Р’РєР°Р¶С–С‚СЊ РЅР°Р·РІСѓ РєР»С–РЅС–РєРё.");
        return;
      }

      saveButton.disabled = true;
      saveButton.textContent = "Р—Р±РµСЂРµР¶РµРЅРЅСЏвЂ¦";

      if (status) {
        status.textContent = "";
        status.className =
          "clinicProfileSaveStatus";
      }

      const saved =
        await saveClinicProfileApi(payload);

      saveButton.disabled = false;
      saveButton.textContent =
        "Р—Р±РµСЂРµРіС‚Рё Р·РјС–РЅРё";

      if (!saved) return;

      if (status) {
        status.textContent =
          "Р—РјС–РЅРё СѓСЃРїС–С€РЅРѕ Р·Р±РµСЂРµР¶РµРЅС–";

        status.classList.add("success");
      }

      const clinicTitle =
        document.getElementById(
          "clinicNameTitle"
        ) ||
        document.querySelector(
          ".clinic-title"
        );

      if (clinicTitle) {
        clinicTitle.textContent =
          saved.name;
      }

      updateClinicDocumentPreview(page);
    }
  );
}

