function renderVisitFiles(visitId) {
  const wrap = document.getElementById("visitFilesList");
  if (!wrap) return;

  const allFiles = LS.get(FILES_KEY, []);
  const byId = new Map((Array.isArray(allFiles) ? allFiles : []).map((f) => [String(f.id), f]));
  const ids = getFileIdsForVisit(visitId);

  if (!ids.length) {
    wrap.innerHTML = `<div class="hint">РџРѕРєРё С„Р°Р№Р»С–РІ РЅРµРјР°С”.</div>`;
    return;
  }

  wrap.innerHTML = ids
    .map((id) => {
      const f = byId.get(String(id));
      if (!f) return "";
      const url = f.url || (f.stored_name ? `/uploads/${f.stored_name}` : "#");
      const name = f.name || f.stored_name || "file";
      return `
        <div class="fileRow">
          <div class="fileMain">
            <div class="fileName">${escapeHtml(name)}</div>
            <div class="fileMeta">${escapeHtml(f.type || "")} ${f.size ? "вЂў " + escapeHtml(String(f.size)) + " bytes" : ""}</div>
          </div>
          <div class="fileActions">
            <a class="miniBtn" href="${escapeHtml(url)}" target="_blank" rel="noopener">Р’С–РґРєСЂРёС‚Рё</a>
            <button type="button" class="miniBtn danger" data-detach-file="${escapeHtml(String(id))}">Р’С–РґРІКјСЏР·Р°С‚Рё</button>
          </div>
        </div>
      `;
    })
    .join("");

  wrap.onclick = (e) => {
    const btn = e.target.closest("[data-detach-file]");
    if (!btn) return;
    e.preventDefault();
    const fid = btn.dataset.detachFile;
    if (!fid) return;
    detachFileFromVisit(visitId, fid);
    renderVisitFiles(visitId);
  };
}

async function updateStaffApi(staffId, payload) {
  try {
    const res = await fetch(`/api/staff/${encodeURIComponent(staffId)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload || {}),
    });
    const json = await res.json();
    if (!json.ok) { alert(json.error || "РџРѕРјРёР»РєР° РѕРЅРѕРІР»РµРЅРЅСЏ РІРµС‚РµСЂРёРЅР°СЂР°"); return null; }
    return json.data || null;
  } catch (e) {
    console.error(e); alert("РџРѕРјРёР»РєР° РѕРЅРѕРІР»РµРЅРЅСЏ РІРµС‚РµСЂРёРЅР°СЂР°"); return null;
  }
}

async function deactivateStaffApi(staffId) {
  try {
    const response = await fetch(
      `/api/staff/${encodeURIComponent(staffId)}`,
      {
        method: "DELETE",
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...getOrgHeaders(),
        },
      }
    );

    const text = await response.text();
    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {
      json = null;
    }

    if (
      !response.ok ||
      json?.ok !== true
    ) {
      return {
        ok: false,
        error:
          json?.error ||
          `HTTP ${response.status}`,
      };
    }

    return {
      ok: true,
      data: json.data || null,
    };
  } catch (error) {
    console.error(
      "deactivateStaffApi failed:",
      error
    );

    return {
      ok: false,
      error:
        "РџРѕРјРёР»РєР° Р·'С”РґРЅР°РЅРЅСЏ РїС–Рґ С‡Р°СЃ Р·РІС–Р»СЊРЅРµРЅРЅСЏ СЃРїС–РІСЂРѕР±С–С‚РЅРёРєР°.",
    };
  }
}

async function renderStaffSpecsBox(selectedIds = []) {
  const box = $("#staffSpecsBox");
  if (!box) return;

  const specs = await loadSpecializationsApi();
  const selected = new Set((selectedIds || []).map(String));

  box.innerHTML = specs.length
    ? specs.map((s) => `
      <label class="staffSpecializationOption">
        <input type="checkbox" data-staff-spec value="${escapeHtml(String(s.id))}" ${selected.has(String(s.id)) ? "checked" : ""}>
        <span class="staffSpecDot" style="background:${escapeHtml(s.color || "#7C5CFF")}"></span>
        <span class="staffSpecializationOptionName">${escapeHtml(s.name || "РќР°РїСЂСЏРј")}</span>
        <span class="staffSpecializationCheckmark">вњ“</span>
      </label>
    `).join("")
    : `<div class="hint">РЎРїРѕС‡Р°С‚РєСѓ РґРѕРґР°Р№ РЅР°РїСЂСЏРјРё РєР»С–РЅС–РєРё РІРёС‰Рµ.</div>`;

  const toggle = $("#staffSpecializationToggle");
  const select = $("#staffSpecializationSelect");

  const updateSummary = () => {
    const summary = $("#staffSpecializationSummary");
    if (!summary) return;

    const checked = Array.from(
      box.querySelectorAll(
        "[data-staff-spec]:checked"
      )
    );

    summary.innerHTML = checked.length
      ? checked
          .map((input) => {
            const option = input.closest(
              ".staffSpecializationOption"
            );

            const name =
              option?.querySelector(
                ".staffSpecializationOptionName"
              )?.textContent?.trim() ||
              "РќР°РїСЂСЏРј";

            const color =
              option?.querySelector(
                ".staffSpecDot"
              )?.style?.background ||
              "#7C5CFF";

            return `
              <span
                class="staffSpecializationChip"
                style="--specialization-color:${escapeHtml(
                  color
                )}"
              >
                ${escapeHtml(name)}
              </span>
            `;
          })
          .join("")
      : `<span class="staffSpecializationPlaceholder">РћР±РµСЂС–С‚СЊ РЅР°РїСЂСЏРјРё</span>`;
  };

  const setOpen = (isOpen) => {
    box.hidden = !isOpen;
    box.setAttribute(
      "aria-hidden",
      String(!isOpen)
    );
    toggle?.setAttribute(
      "aria-expanded",
      String(isOpen)
    );
    select?.classList.toggle(
      "open",
      isOpen
    );
  };

  if (toggle) {
    toggle.onclick = () =>
      setOpen(box.hidden);
  }

  box.onchange = () => {
  updateSummary();

  setOpen(false);

  if (toggle) {
    toggle.focus();
  }
};

  setOpen(false);
  updateSummary();
}

