const visitRabiesStatus =
  $("#visitNewPetRabiesStatus");

const visitGeneralVaccinationStatus =
  $("#visitNewPetGeneralVaccinationStatus");

const visitRabiesDetails =
  $("#visitNewPetRabiesDetails");

