async function loadStaffScheduleRangeApi(
  from,
  to
) {
  const maxAttempts = 3;

  const delays = [
    0,
    500,
    1000,
  ];

  let lastError = null;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt++
  ) {
    if (delays[attempt - 1]) {
      await new Promise(
        (resolve) =>
          setTimeout(
            resolve,
            delays[attempt - 1]
          )
      );
    }

    try {
      const response =
        await fetch(
          `/api/staff-schedule-range?from=${
            encodeURIComponent(from)
          }&to=${
            encodeURIComponent(to)
          }`,
          {
            method: "GET",

            credentials:
              "include",

            cache:
              "no-store",

            headers: {
              Accept:
                "application/json",

              ...getOrgHeaders(),
            },
          }
        );

      const text =
        await response.text();

      let json = null;

      try {
        json =
          text
            ? JSON.parse(text)
            : null;
      } catch {
        json = null;
      }

      if (
        !response.ok ||
        json?.ok !== true
      ) {
        throw new Error(
          json?.error ||
          `HTTP ${response.status}`
        );
      }

      const rows =
        Array.isArray(
          json.data
        )
          ? json.data
          : [];

      if (attempt > 1) {
        console.info(
          `loadStaffScheduleRangeApi restored on attempt ${attempt}`
        );
      }

      return rows;

    } catch (error) {
      lastError =
        error;

      console.warn(
        `loadStaffScheduleRangeApi attempt ${attempt}/${maxAttempts} failed:`,
        error
      );
    }
  }

  console.error(
    "loadStaffScheduleRangeApi failed after retries:",
    lastError
  );

  return [];
}
async function loadStaffRatingApi() {
  const emptyRating = {
    season_key: "вЂ”",
    rows: [],
  };

  try {
    const headers = {
      Accept: "application/json",
      ...getOrgHeaders(),
    };

    // РЎРЅР°С‡Р°Р»Р° РїСЂРѕР±СѓРµРј РїРѕР»СѓС‡РёС‚СЊ РіРѕС‚РѕРІС‹Р№ СЂРµР№С‚РёРЅРі СЃРµР·РѕРЅР°.
    const ratingResponse = await fetch(
      "/api/staff/rating",
      {
        method: "GET",
        credentials: "include",
        headers,
      }
    );

    const ratingJson =
      await ratingResponse.json();

    if (
      !ratingResponse.ok ||
      ratingJson?.ok !== true
    ) {
      throw new Error(
        ratingJson?.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё СЂРµР№С‚РёРЅРі."
      );
    }

    const rating =
      ratingJson.data || emptyRating;

    if (
      Array.isArray(rating.rows) &&
      rating.rows.length > 0
    ) {
      return rating;
    }

    // РЇРєС‰Рѕ СЃРµР·РѕРЅ С‰Рµ РїРѕСЂРѕР¶РЅС–Р№ вЂ”
    // Р°РІС‚РѕРјР°С‚РёС‡РЅРѕ СЃС‚РІРѕСЂСЋС”РјРѕ СЂРµР№С‚РёРЅРі.
    const rebuildResponse = await fetch(
      "/api/staff/rating/rebuild",
      {
        method: "POST",
        credentials: "include",
        headers,
      }
    );

    const rebuildJson =
      await rebuildResponse.json();

    if (
      !rebuildResponse.ok ||
      rebuildJson?.ok !== true
    ) {
      throw new Error(
        rebuildJson?.error ||
        "РќРµ РІРґР°Р»РѕСЃСЏ СЂРѕР·СЂР°С…СѓРІР°С‚Рё СЂРµР№С‚РёРЅРі."
      );
    }

    return (
      rebuildJson.data || {
        season_key:
          rating.season_key || "вЂ”",
        rows: [],
      }
    );
  } catch (error) {
    console.error(
      "loadStaffRatingApi failed:",
      error
    );

    return emptyRating;
  }
}
