function ownerModalHasChanges() {
  const modal =
    $("#ownerModal");

  if (!modal) {
    return false;
  }

  let initialState = {};

  try {
    initialState =
      JSON.parse(
        modal.dataset
          .initialState ||
        "{}"
      );
  } catch {
    initialState = {};
  }

  const currentState =
    getOwnerModalState();

  return (
    JSON.stringify(
      currentState
    ) !==
    JSON.stringify(
      initialState
    )
  );
}

function requestCloseOwnerModal() {
  if (
    !ownerModalHasChanges()
  ) {
    closeOwnerModal();
    return;
  }

  openDeleteModal(
    (
      "Р’РЅРµСЃРµРЅС– РґР°РЅС– РІР»Р°СЃРЅРёРєР° " +
      "С‰Рµ РЅРµ Р·Р±РµСЂРµР¶РµРЅС–."
    ),
    () => {
      closeOwnerModal();
    },
    "unsaved"
  );
}
function closeOwnerModal() {
  const modal =
    $("#ownerModal");

  if (!modal) {
    return;
  }

  modal.classList.remove(
    "open",
    "show"
  );

  modal.setAttribute(
    "aria-hidden",
    "true"
  );

  modal.style.display =
    "none";

  modal.dataset.ownerId =
    "";

    modal.dataset.initialState =
  "";

  const idInput =
    $("#ownerModalId");

  if (idInput) {
    idInput.value = "";
  }
}

